// Traducción al inglés de las fichas (capa sobre data/anatomia.js). Mismo orden que `concepts`.
// English translation layer for the anatomical cards (overlay on data/anatomia.js). Same order as `concepts`.
// Translated from the Spanish originals; not reviewed by specialists.
(window.ANAT_I18N=window.ANAT_I18N||{}).en={"systems":{"teg":{"n":"Integumentary","d":"Skin and cutaneous appendages (hair). The largest organ of the body: it protects against physical, chemical and microbial aggression, regulates temperature and houses sensory receptors."},"mus":{"n":"Muscular","d":"Skeletal muscles, tendons, aponeuroses and associated ligaments. They produce movement, maintain posture and generate heat. The human body has more than 600 skeletal muscles."},"esq":{"n":"Skeletal","d":"Bones, cartilages and intervertebral discs. The adult skeleton has about 206 bones: it supports the body, protects organs, acts as a lever for muscles, stores calcium and phosphorus and houses the hematopoietic bone marrow."},"ner":{"n":"Nervous and senses","d":"Brain, optic pathways, ventricular system and sense organs. It integrates sensory information and coordinates the body's responses."},"car":{"n":"Cardiovascular","d":"Heart and great vessels. At rest the heart pumps about 5 litres of blood per minute through the systemic and pulmonary circulations."},"res":{"n":"Respiratory","d":"Airways and lungs. They allow the exchange of oxygen and carbon dioxide between air and blood."},"dig":{"n":"Digestive","d":"Digestive tract from the mouth to the anus and accessory glands (liver, gallbladder, pancreas). It digests food and absorbs nutrients and water."},"uri":{"n":"Urinary","d":"Kidneys, ureters, bladder and urethra. It filters the blood, regulates fluid-electrolyte and acid-base balance and eliminates waste in the urine."},"rep":{"n":"Male reproductive","d":"Testes, spermatic ducts, accessory glands and penis. The source model (BodyParts3D) corresponds to an adult male."},"end":{"n":"Endocrine","d":"Glands that release hormones into the blood. In this model: pituitary gland, pineal gland and adrenal glands."},"lin":{"n":"Lymphatic and immune","d":"Lymphoid organs: spleen and thymus. They take part in immune defence and, in the case of the spleen, in filtering the blood."}},"concepts":[["Anterior interventricular branch (left anterior descending)","Heart: coronary arteries","Branch of the left coronary artery that descends in the anterior interventricular groove. It supplies the anterior surface of both ventricles and the anterior 2/3 of the septum. The coronary arteries supply the myocardium itself; their obstruction causes ischaemia and infarction.",[]],["Circumflex branch of the left coronary artery","Heart: coronary arteries","It runs in the left coronary groove to the posterior surface of the heart and supplies the atrium and the lateral wall of the left ventricle. The coronary arteries supply the myocardium itself; their obstruction causes ischaemia and infarction.",[]],["Left gastric artery","Major arteries (abdominal)","Branch of the celiac trunk that runs along the lesser curvature of the stomach and gives off oesophageal branches.",[]],["Inferior lobe of the left lung","Lungs","Lobe below the oblique fissure of the left lung; it forms most of the diaphragmatic and posterior surfaces. The lungs contain ≈300–500 million alveoli, with an exchange surface of ≈70 m².",[]],["Inferior lobe of the right lung","Lungs","Basal and posterior lobe of the right lung, below the oblique fissure. It has five segments (superior and four basal). The lungs contain ≈300–500 million alveoli, with an exchange surface of ≈70 m².",[]],["Right marginal branch","Heart: coronary arteries","Branch of the right coronary artery that descends along the right (acute) margin of the heart and supplies the right ventricle. The coronary arteries supply the myocardium itself; their obstruction causes ischaemia and infarction.",[]],["Middle lobe of the right lung","Lungs","Lobe exclusive to the right lung, bounded by the horizontal and oblique fissures. It has two segments: lateral and medial. The lungs contain ≈300–500 million alveoli, with an exchange surface of ≈70 m².",[]],["Posterior interventricular branch (posterior descending)","Heart: coronary arteries","It descends in the posterior interventricular groove and supplies the posterior third of the septum and the inferior surface of the ventricles. It arises from the right coronary artery in ≈80 % of people (right dominance). The coronary arteries supply the myocardium itself; their obstruction causes ischaemia and infarction.",[]],["Posterior papillary muscle of the left ventricle","Heart","Projection of the left ventricular myocardium attached by chordae tendineae to the cusps of the mitral valve. It prevents their prolapse during systole.",[]],["Posterior papillary muscle of the right ventricle","Heart","Projection of the right ventricular myocardium attached by chordae tendineae to the tricuspid valve. It prevents their prolapse during systole.",[]],["Right posterolateral branch","Heart: coronary arteries","Terminal branch of the right coronary artery that supplies the posterolateral surface of the left ventricle. The coronary arteries supply the myocardium itself; their obstruction causes ischaemia and infarction.",[]],["Septal branches of the left coronary artery","Heart: coronary arteries","Branches of the anterior interventricular artery that penetrate the anterior 2/3 of the interventricular septum, where the conduction system runs. The coronary arteries supply the myocardium itself; their obstruction causes ischaemia and infarction.",[]],["Septal branches of the right coronary artery","Heart: coronary arteries","Small branches that penetrate the posterior third of the interventricular septum. The coronary arteries supply the myocardium itself; their obstruction causes ischaemia and infarction.",[]],["Posterior veins of the left ventricle","Heart: cardiac veins","They drain the diaphragmatic surface of the left ventricle into the coronary sinus.",[]],["Left coronary artery trunk","Heart: coronary arteries","It arises from the left aortic sinus and, after a short course (≈1 cm), divides into the anterior interventricular and circumflex branches. The coronary arteries supply the myocardium itself; their obstruction causes ischaemia and infarction.",[]],["Right coronary artery","Heart: coronary arteries","It arises from the right aortic sinus and runs in the right coronary groove. It supplies the right atrium and ventricle and, in most people, the sinoatrial and atrioventricular nodes. The coronary arteries supply the myocardium itself; their obstruction causes ischaemia and infarction.",[]],["Superior lobe of the left lung","Lungs","Upper lobe of the left lung. It includes the lingula, equivalent to the right middle lobe, and the cardiac notch that leaves room for the heart. The lungs contain ≈300–500 million alveoli, with an exchange surface of ≈70 m².",[["Left lung","2 lobes, 8–10 segments"]]],["Superior lobe of the right lung","Lungs","Apical lobe of the right lung, separated from the middle lobe by the horizontal fissure. It has three segments: apical, posterior and anterior. The lungs contain ≈300–500 million alveoli, with an exchange surface of ≈70 m².",[["Right lung","3 lobes, 10 segments"]]],["Pectoralis major — abdominal part","Thorax","Skeletal muscle. It adducts and lowers the arm.",[["Origin","Anterior layer of the rectus sheath"],["Insertion","Crest of the greater tubercle of the humerus"],["Action","Adducts and lowers the arm"],["Innervation","Medial pectoral nerve (C8–T1)"]]],["Abductor digiti minimi (foot)","Lower limb: foot (sole, 1st layer)","Skeletal muscle. It abducts and flexes the fifth toe.",[["Origin","Calcaneal tuberosity"],["Insertion","Base of the proximal phalanx of the fifth toe"],["Action","Abducts and flexes the fifth toe"],["Innervation","Lateral plantar nerve (S2–S3)"]]],["Abductor digiti minimi (hand)","Upper limb: hand (hypothenar eminence)","Skeletal muscle. It abducts the little finger.",[["Origin","Pisiform"],["Insertion","Base of the proximal phalanx of the fifth toe"],["Action","Abducts the little finger"],["Innervation","Ulnar nerve (deep branch)"]]],["Abductor hallucis","Lower limb: foot (sole, 1st layer)","Skeletal muscle. It abducts and flexes the big toe; it supports the medial arch.",[["Origin","Calcaneal tuberosity (medial process)"],["Insertion","Base of the proximal phalanx of the big toe (medial)"],["Action","Abducts and flexes the big toe; supports the medial arch"],["Innervation","Medial plantar nerve (S2–S3)"]]],["Abductor pollicis brevis","Upper limb: hand (thenar eminence)","Skeletal muscle. It abducts the thumb.",[["Origin","Flexor retinaculum, scaphoid and trapezium"],["Insertion","Base of the proximal phalanx of the thumb (radial side)"],["Action","Abducts the thumb"],["Innervation","Median nerve (recurrent branch)"]]],["Abductor pollicis longus","Upper limb: forearm (posterior)","Skeletal muscle. It abducts and extends the thumb.",[["Origin","Posterior surfaces of the ulna and radius and interosseous membrane"],["Insertion","Base of the first metacarpal"],["Action","Abducts and extends the thumb"],["Innervation","Posterior interosseous nerve (of the radial)"]]],["Accessory short gyrus of the insula","Brain: cerebral cortex","Gyrus of the cerebral cortex (grey matter). Small gyrus of the anterior part of the insula.",[["Lobe","Insular"]]],["Deltoid — acromial (middle) part","Upper limb: shoulder","Skeletal muscle. It abducts the arm (from 15° to 90°, after initiation by the supraspinatus).",[["Origin","Lateral border of the acromion"],["Insertion","Deltoid tuberosity of the humerus"],["Action","Abducts the arm (from 15° to 90°, after initiation by the supraspinatus)"],["Innervation","Axillary nerve (C5–C6)"]]],["Adductor brevis","Lower limb: thigh (medial)","Skeletal muscle. It adducts the thigh.",[["Origin","Body and inferior ramus of the pubis"],["Insertion","Proximal part of the linea aspera"],["Action","Adducts the thigh"],["Innervation","Obturator nerve (L2–L4)"]]],["Adductor longus","Lower limb: thigh (medial)","Skeletal muscle. It adducts the thigh.",[["Origin","Body of the pubis, below the crest"],["Insertion","Middle third of the linea aspera"],["Action","Adducts the thigh"],["Innervation","Obturator nerve (L2–L4)"]]],["Adductor magnus","Lower limb: thigh (medial)","The largest of the adductors; between its insertions it leaves the adductor hiatus, through which the femoral vessels pass to the popliteal fossa.",[["Origin","Ischiopubic ramus and ischial tuberosity"],["Insertion","Linea aspera and adductor tubercle of the femur"],["Action","Adducts the thigh; its ischial part extends the hip"],["Innervation","Obturator nerve (L2–L4) and tibial part of the sciatic nerve"]]],["Adductor minimus","Lower limb: thigh (medial)","Upper portion, often separate, of the adductor magnus.",[["Origin","Inferior ramus of the pubis"],["Insertion","Proximal part of the linea aspera"],["Action","Adducts and laterally rotates the thigh"],["Innervation","Obturator nerve (L2–L4)"]]],["Adrenal gland","Endocrine glands","Gland located on the upper pole of each kidney. The cortex produces cortisol, aldosterone and androgens; the medulla, adrenaline and noradrenaline.",[["Weight","≈4–5 g"],["Parts","Cortex (glomerular, fascicular, reticular) and medulla"]]],["Amygdala (amygdaloid body)","Brain: deep nuclei","Almond-shaped group of nuclei in the anterior part of the temporal lobe. It processes emotions, especially fear, and assigns emotional value to memories.",[["Group","Limbic system"]]],["Anconeus","Upper limb: arm","Skeletal muscle. It helps extend the elbow and stabilises the joint.",[["Origin","Lateral epicondyle of the humerus"],["Insertion","Lateral surface of the olecranon"],["Action","Helps extend the elbow and stabilises the joint"],["Innervation","Radial nerve (C6–C8)"]]],["Angular gyrus","Brain: cerebral cortex","Gyrus of the cerebral cortex (grey matter). It surrounds the end of the superior temporal sulcus. In the dominant hemisphere it is key for reading, writing and calculation.",[["Lobe","Parietal (inferior)"],["Area","Brodmann 39"]]],["Digastric — anterior belly","Neck (suprahyoid)","Skeletal muscle. It depresses the mandible and elevates the hyoid.",[["Origin","Digastric fossa of the mandible"],["Insertion","Intermediate tendon, attached to the hyoid"],["Action","Depresses the mandible and elevates the hyoid"],["Innervation","Mylohyoid nerve (from V3)"]]],["Anterior commissure","Brain: white matter","Bundle of fibres that crosses the midline in front of the fornix; it connects the temporal lobes and olfactory structures of both hemispheres.",[]],["Internal capsule — anterior limb","Brain: white matter","Sheet of white matter between the caudate nucleus and the lentiform nucleus. It contains fibres between the thalamus and the frontal cortex and frontopontine fibres.",[]],["Anterior papillary muscle of the right ventricle","Heart","Conical projection of the ventricular myocardium attached to the cusps by the chordae tendineae. By contracting in systole it prevents the atrioventricular valve cusps from bulging back into the atrium.",[]],["Superior temporal gyrus (anterior part)","Brain: cerebral cortex","Gyrus of the cerebral cortex (grey matter). Its upper surface contains the primary auditory cortex (transverse gyri of Heschl).",[["Lobe","Temporal"]]],["Epicranial aponeurosis (galea aponeurotica)","Head: muscles of facial expression","Tough tendinous sheet that covers the cranial vault and joins the frontal and occipital bellies of the occipitofrontalis muscle. It is firmly attached to the skin of the scalp.",[["Type","Dense connective tissue (aponeurosis)"]]],["Vermiform appendix","Digestive tract","Narrow blind diverticulum (≈8 cm) that arises from the caecum. Rich in lymphoid tissue. Its inflammation (appendicitis) is the most frequent abdominal surgical emergency.",[["Length","≈6–10 cm"]]],["Aortic arch","Major arteries","Curved portion of the aorta over the left main bronchus. The brachiocephalic trunk, the left common carotid and the left subclavian arise from it.",[]],["Ascending aorta","Major arteries","First segment of the aorta, from the aortic valve to the arch (≈5 cm). The coronary arteries arise from its root.",[["Diameter","≈3 cm"]]],["Trapezius — ascending part","Back: superficial muscles","Skeletal muscle. It lowers the scapula and helps its upward rotation.",[["Origin","Spinous processes of T4–T12"],["Insertion","Tubercle of the spine of the scapula"],["Action","Lowers the scapula and helps its upward rotation"],["Innervation","Accessory nerve (XI)"]]],["Atlas (C1)","Vertebral column","First cervical vertebra. It has no body or spinous process: it is a ring with two lateral masses that support the skull. The atlanto-occipital joint allows flexion and extension of the head (\"saying yes\").",[["Articulates with","Occipital and axis"]]],["Axis (C2)","Vertebral column","Second cervical vertebra. Its dens (odontoid process) acts as a pivot around which the atlas turns: the atlantoaxial joint allows rotation of the head (\"saying no\").",[]],["Body of the sternum","Thoracic cage","Central and longest portion of the sternum. The 2nd to 7th costal cartilages articulate with its lateral borders.",[]],["Brachialis","Upper limb: arm","Skeletal muscle. Main flexor of the elbow in any position of the forearm.",[["Origin","Distal half of the anterior surface of the humerus"],["Insertion","Coronoid process and tuberosity of the ulna"],["Action","Main flexor of the elbow in any position of the forearm"],["Innervation","Musculocutaneous nerve (C5–C6) and branch of the radial nerve"]]],["Brachiocephalic trunk","Major arteries","First and largest branch of the aortic arch. After the right sternoclavicular joint it divides into the right common carotid and subclavian arteries.",[]],["Brachiocephalic vein","Major veins","Formed by the union of the internal jugular and subclavian veins behind the sternoclavicular joint. The left one is longer and crosses in front of the branches of the aortic arch.",[]],["Brachioradialis","Upper limb: forearm (posterior)","Skeletal muscle. It flexes the elbow, especially in semipronation.",[["Origin","Lateral supracondylar ridge of the humerus"],["Insertion","Base of the styloid process of the radius"],["Action","Flexes the elbow, especially in semipronation"],["Innervation","Radial nerve (C6–C8)"]]],["Brachium of the inferior colliculus","Brain: brainstem and cerebellum","Bundle of fibres joining the inferior colliculus with the medial geniculate body (auditory pathway).",[]],["Brachium of the superior colliculus","Brain: brainstem and cerebellum","Bundle of fibres joining the optic tract and the lateral geniculate body with the superior colliculus.",[]],["Bronchi","Airways","Bronchial tree: the main bronchi divide into lobar and segmental bronchi. The right main bronchus is shorter, wider and more vertical, so aspirated foreign bodies usually go to the right.",[]],["Buccinator","Head: muscles of facial expression","Skeletal muscle. It presses the cheek against the teeth; it keeps food between the dental arches and allows blowing.",[["Origin","Alveolar processes of the maxilla and mandible and pterygomandibular raphe"],["Insertion","Angle of the mouth and orbicularis oris"],["Action","Compresses the cheek against the teeth; keeps food between the dental arches and allows blowing"],["Innervation","Facial nerve (VII), buccal branches"]]],["Calcaneal (Achilles) tendon","Lower limb: leg (posterior) (triceps surae)","Common tendon of the gastrocnemius and soleus, the thickest and strongest in the body. It inserts on the calcaneal tuberosity and transmits the force of plantar flexion.",[["Length","≈15 cm"],["Clinical note","Rupture from strain; Achilles reflex (S1)"]]],["Calcaneus","Foot: tarsus","Short bone of the tarsus. The seven tarsal bones form the posterior skeleton of the foot. It is the largest bone of the foot and forms the heel; the calcaneal (Achilles) tendon inserts on its tuberosity.",[]],["Capitate","Hand: carpus","Short bone of the carpus. The eight carpal bones are arranged in two rows and form the skeleton of the wrist. Distal row; it is the largest carpal bone and articulates with the third metacarpal.",[]],["Caudate nucleus","Brain: deep nuclei","C-shaped nucleus of grey matter that follows the wall of the lateral ventricle. With the putamen it forms the striatum: movement planning, learning and motivation.",[["Group","Basal ganglia"]]],["Celiac trunk","Major arteries (abdominal)","First visceral branch of the abdominal aorta (T12). It divides into the left gastric, splenic and common hepatic arteries: it supplies the stomach, liver, spleen, pancreas and duodenum.",[]],["Central canal of the spinal cord","Brain: ventricular system","Narrow canal, continuation of the fourth ventricle, running through the centre of the spinal cord. (The spinal cord itself is not represented in this model.)",[]],["Cerebellum","Brain: brainstem and cerebellum","Organ located in the posterior cranial fossa, behind the brainstem. It coordinates movement, balance and muscle tone, and takes part in motor learning. It contains more neurons than the rest of the brain.",[["Weight","≈150 g"],["Parts","Vermis and two hemispheres"]]],["Cerebral aqueduct (of Sylvius)","Brain: ventricular system","Narrow canal of the midbrain joining the third and fourth ventricles. Its obstruction is a frequent cause of hydrocephalus.",[]],["Cervical rotator muscles","Back: deep muscles (erector spinae) (transversospinal)","Skeletal muscle. They stabilise and rotate the spine; proprioceptive function.",[["Origin","Transverse processes of the cervical vertebrae"],["Insertion","Lamina or spinous process of the vertebra 1–2 levels above"],["Action","Stabilise and rotate the spine; proprioceptive function"],["Innervation","Posterior rami of the spinal nerves"]]],["Choroid plexus of the lateral ventricle","Brain: ventricular system","Network of capillaries covered by ependymal epithelium that produces cerebrospinal fluid (≈500 ml/day).",[]],["Cingulate gyrus","Brain: cerebral cortex","Gyrus of the cerebral cortex (grey matter). It surrounds the corpus callosum on the medial surface of the hemisphere. Part of the limbic system: emotions, motivation, attention, pain and error monitoring.",[["Lobe","Limbic"]]],["Clavicle","Upper limb","Long bone shaped like an italic S that joins the upper limb to the trunk. It articulates medially with the sternum and laterally with the acromion of the scapula. It is the most frequently fractured bone.",[["Joints","Sternoclavicular and acromioclavicular"]]],["Deltoid — clavicular (anterior) part","Upper limb: shoulder","Anterior part of the deltoid, the muscle that gives the shoulder its rounded shape.",[["Origin","Lateral third of the clavicle"],["Insertion","Deltoid tuberosity of the humerus"],["Action","Flexes and medially rotates the arm"],["Innervation","Axillary nerve (C5–C6)"]]],["Pectoralis major — clavicular part","Thorax","Upper part of the pectoralis major, a large fan-shaped muscle of the anterior chest wall.",[["Origin","Medial half of the clavicle"],["Insertion","Crest of the greater tubercle of the humerus"],["Action","Flexes the arm and adducts and medially rotates it"],["Innervation","Lateral pectoral nerve (C5–C7)"]]],["Coccygeus (ischiococcygeus)","Pelvis: pelvic floor","Skeletal muscle. It supports the pelvic viscera and flexes the coccyx.",[["Origin","Ischial spine"],["Insertion","Lateral borders of the coccyx and lower sacrum"],["Action","Supports the pelvic viscera and flexes the coccyx"],["Innervation","Branches of S3–S4"]]],["Colon","Digestive tract","Part of the large intestine between the caecum and the rectum: ascending, transverse, descending and sigmoid. It absorbs water and electrolytes and forms the faeces. It has haustra, taeniae coli and omental appendices.",[["Length","≈1.5 m"]]],["Commissure of the fornix","Brain: white matter","Fibres that cross between the posterior pillars of both fornices, connecting the two hippocampi.",[]],["Common carotid artery","Major arteries","It ascends the neck and, at the level of the upper border of the thyroid cartilage (C4), divides into the external carotid (face and neck) and internal carotid (brain and eye). At its bifurcation lies the carotid sinus, a blood pressure sensor.",[]],["Common hepatic artery","Major arteries (abdominal)","Branch of the celiac trunk that supplies the liver, gallbladder, stomach (lesser and greater curvatures), duodenum and pancreas.",[]],["Common iliac artery","Major arteries (pelvis)","Terminal branch of the aorta (L4). It divides in front of the sacroiliac joint into the external and internal iliac arteries.",[]],["Common iliac vein","Major veins (pelvis)","Formed by the union of the external and internal iliac veins. Both join at the level of L5 to form the inferior vena cava.",[]],["Coracobrachialis","Upper limb: arm","Skeletal muscle. It flexes and adducts the arm.",[["Origin","Coracoid process of the scapula"],["Insertion","Middle third of the medial surface of the humerus"],["Action","Flexes and adducts the arm"],["Innervation","Musculocutaneous nerve (C5–C6)"]]],["Coronary sinus","Heart: cardiac veins","Wide vein in the posterior coronary groove that collects most of the venous blood of the heart and drains into the right atrium.",[]],["Corpus callosum","Brain: white matter","The largest commissure of the brain: about 200 million axons that connect the two cerebral hemispheres and allow information to be shared between them.",[["Parts","Rostrum, genu, body and splenium"]]],["Corpora cavernosa of the penis","Male reproductive system","Two cylinders of erectile tissue on the dorsal side of the penis. When they fill with blood they produce the erection.",[]],["Corpus spongiosum of the penis","Male reproductive system","Cylinder of erectile tissue on the ventral side of the penis that surrounds the spongy urethra and ends in the glans.",[]],["Corrugator supercilii","Head: muscles of facial expression","Skeletal muscle. It pulls the eyebrow down and in (frowning).",[["Origin","Medial end of the superciliary arch"],["Insertion","Skin of the middle of the eyebrow"],["Action","Pulls the eyebrow down and in (frowning)"],["Innervation","Facial nerve (VII), temporal branches"]]],["Costal cartilages (8th–10th)","Thoracic cage","Hyaline cartilages of the false ribs. They join one another and the seventh cartilage, forming the costal margin or arch.",[]],["Cuboid","Foot: tarsus","Short bone of the tarsus. The seven tarsal bones form the posterior skeleton of the foot. Located on the lateral border of the foot; the tendon of the fibularis longus runs in its groove.",[]],["Flexor pollicis brevis — deep head","Upper limb: hand (thenar eminence)","Skeletal muscle. It flexes the thumb.",[["Origin","Trapezoid and capitate"],["Insertion","Base of the proximal phalanx of the thumb"],["Action","Flexes the thumb"],["Innervation","Ulnar nerve (deep branch)"]]],["Masseter — deep part","Head: muscles of mastication","Skeletal muscle. It elevates the mandible and helps retract it.",[["Origin","Medial surface of the zygomatic arch"],["Insertion","Lateral surface of the ramus and coronoid process of the mandible"],["Action","Elevates the mandible and helps retract it"],["Innervation","Mandibular nerve (V3), branch of the trigeminal, masseteric nerve"]]],["Ductus (vas) deferens","Male reproductive system","Muscular duct of ≈45 cm that carries the sperm from the epididymis, through the inguinal canal and the pelvis, to the ejaculatory duct.",[["Length","≈45 cm"]]],["Depressor anguli oris","Head: muscles of facial expression","Skeletal muscle. It depresses the angle of the mouth (expression of sadness).",[["Origin","Oblique line of the mandible"],["Insertion","Angle of the mouth"],["Action","Depresses the angle of the mouth (expression of sadness)"],["Innervation","Facial nerve (VII), mandibular branches"]]],["Depressor labii inferioris","Head: muscles of facial expression","Skeletal muscle. It depresses and everts the lower lip.",[["Origin","Oblique line of the mandible"],["Insertion","Skin of the lower lip"],["Action","Depresses and everts the lower lip"],["Innervation","Facial nerve (VII), marginal mandibular branch"]]],["Depressor septi nasi","Head: muscles of facial expression","Skeletal muscle. It pulls the septum down and dilates the nostril.",[["Origin","Incisive fossa of the maxilla"],["Insertion","Mobile septum of the nose"],["Action","Pulls the septum down and dilates the nostril"],["Innervation","Facial nerve (VII), buccal branches"]]],["Descending aorta","Major arteries","Continuation of the aortic arch: the thoracic part descends beside the spine, crosses the diaphragm (T12) and as the abdominal aorta bifurcates into the common iliac arteries at L4.",[]],["Trapezius — descending part","Back: superficial muscles","Upper part of the trapezius, a large flat triangular muscle of the nape and back.",[["Origin","Superior nuchal line, external occipital protuberance and nuchal ligament"],["Insertion","Lateral third of the clavicle"],["Action","Elevates the scapula (shrugging) and rotates it upward"],["Innervation","Accessory nerve (XI); proprioception from C3–C4"]]],["Diaphragm","Thorax","Dome-shaped musculotendinous septum that separates the thorax from the abdomen. It is the main respiratory muscle; the inferior vena cava (T8), the oesophagus (T10) and the aorta (T12) pass through it.",[["Origin","Xiphoid process, costal cartilages 7–12 and vertebrae L1–L3 (crura)"],["Insertion","Central tendon"],["Action","Main muscle of inspiration: when it contracts it descends and increases the thoracic volume"],["Innervation","Phrenic nerve (C3–C5)"]]],["Distal phalanx of the big toe (hallux)","Foot: phalanges","Bone of the toes. They are shorter than those of the hand; the big toe has only two phalanges.",[]],["Distal phalanx of the fourth toe","Foot: phalanges","Bone of the toes. They are shorter than those of the hand; the big toe has only two phalanges.",[]],["Distal phalanx of the index finger","Hand: phalanges","Miniature long bone of the fingers. Terminal part of the digit; its tuberosity supports the pulp and the nail.",[]],["Distal phalanx of the little finger","Hand: phalanges","Miniature long bone of the fingers. Terminal part of the digit; its tuberosity supports the pulp and the nail.",[]],["Distal phalanx of the fifth toe","Foot: phalanges","Bone of the toes. They are shorter than those of the hand; the big toe has only two phalanges.",[]],["Distal phalanx of the middle finger","Hand: phalanges","Miniature long bone of the fingers. Terminal part of the digit; its tuberosity supports the pulp and the nail.",[]],["Distal phalanx of the ring finger","Hand: phalanges","Miniature long bone of the fingers. Terminal part of the digit; its tuberosity supports the pulp and the nail.",[]],["Distal phalanx of the second toe","Foot: phalanges","Bone of the toes. They are shorter than those of the hand; the big toe has only two phalanges.",[]],["Distal phalanx of the third toe","Foot: phalanges","Bone of the toes. They are shorter than those of the hand; the big toe has only two phalanges.",[]],["Distal phalanx of the thumb","Hand: phalanges","Miniature long bone of the fingers. Terminal part of the digit; its tuberosity supports the pulp and the nail.",[]],["Duodenum","Digestive tract","First part of the small intestine (≈25 cm), C-shaped around the head of the pancreas. The common bile duct and the pancreatic duct open into its second part (ampulla of Vater).",[["Length","≈25 cm"]]],["Ears (auricles)","Sense organs","Visible part of the outer ear, formed by elastic cartilage covered with skin (except the lobule). It collects sound waves and directs them to the external acoustic meatus.",[["Tissue","Elastic cartilage"]]],["Eighth rib","Thoracic cage","False rib (vertebrochondral): its cartilage joins that of the rib above, forming the costal arch.",[["No.","8th of 12 pairs"]]],["T8 vertebra","Vertebral column","Thoracic vertebra: it has costal facets on the body and on the transverse processes to articulate with the ribs, and a long spinous process pointing downward.",[]],["Eleventh rib","Thoracic cage","Floating rib: its anterior end ends free in the muscles of the abdominal wall.",[["No.","11th of 12 pairs"]]],["T11 vertebra","Vertebral column","Thoracic vertebra: it has costal facets on the body and on the transverse processes to articulate with the ribs, and a long spinous process pointing downward. Its costal facets are complete and single; it no longer articulates with the transverse processes.",[]],["Epididymis","Male reproductive system","Highly coiled duct (≈6 m if unrolled) attached to the posterior border of the testis, where sperm mature and are stored.",[]],["Oesophagus","Digestive tract","Muscular tube of ≈25 cm that carries the food bolus from the pharynx to the stomach by peristaltic waves. It crosses the diaphragm at the level of T10. Its upper third has striated muscle and the lower two thirds, smooth muscle.",[["Length","≈25 cm"]]],["Ethmoid bone","Skull","Unpaired, light bone located between the orbits. It forms part of the roof and walls of the nasal cavities; its cribriform plate lets the filaments of the olfactory nerve pass.",[["Parts","Cribriform plate, perpendicular plate and ethmoidal labyrinths"]]],["Extensor carpi radialis brevis","Upper limb: forearm (posterior)","Its tendon of origin is the one most affected in lateral epicondylitis (\"tennis elbow\").",[["Origin","Lateral epicondyle of the humerus"],["Insertion","Base of the third metacarpal (dorsal)"],["Action","Extends and abducts the wrist"],["Innervation","Radial nerve (deep branch)"]]],["Extensor carpi radialis longus","Upper limb: forearm (posterior)","Skeletal muscle. It extends and abducts the wrist.",[["Origin","Lateral supracondylar ridge of the humerus"],["Insertion","Base of the second metacarpal (dorsal)"],["Action","Extends and abducts the wrist"],["Innervation","Radial nerve (C6–C8)"]]],["Extensor digiti minimi","Upper limb: forearm (posterior)","Skeletal muscle. It extends the little finger.",[["Origin","Lateral epicondyle of the humerus"],["Insertion","Extensor expansion of the fifth finger"],["Action","Extends the little finger"],["Innervation","Posterior interosseous nerve (of the radial)"]]],["Extensor digitorum","Upper limb: forearm (posterior)","Skeletal muscle. It extends the fingers and the wrist.",[["Origin","Lateral epicondyle of the humerus"],["Insertion","Extensor expansions of fingers 2–5"],["Action","Extends the fingers and the wrist"],["Innervation","Posterior interosseous nerve (of the radial)"]]],["Extensor digitorum brevis","Lower limb: foot (dorsum)","Skeletal muscle. It extends the 2nd–4th fingers.",[["Origin","Superolateral surface of the calcaneus"],["Insertion","Tendons of the extensor digitorum longus to toes 2–4"],["Action","Extends toes 2–4"],["Innervation","Deep fibular nerve (L4–L5)"]]],["Extensor digitorum longus","Lower limb: leg (anterior)","Skeletal muscle. It extends the fingers and dorsiflexes the foot.",[["Origin","Lateral condyle of the tibia, fibula and interosseous membrane"],["Insertion","Middle and distal phalanges of toes 2–5"],["Action","Extends the toes and dorsiflexes the foot"],["Innervation","Deep fibular nerve (L4–L5)"]]],["Extensor hallucis brevis","Lower limb: foot (dorsum)","Skeletal muscle. It extends the big toe.",[["Origin","Superolateral surface of the calcaneus"],["Insertion","Base of the proximal phalanx of the big toe"],["Action","Extends the big toe"],["Innervation","Deep fibular nerve (L4–L5)"]]],["Extensor hallucis longus","Lower limb: leg (anterior)","Skeletal muscle. It extends the big toe and dorsiflexes the foot.",[["Origin","Medial surface of the fibula and interosseous membrane"],["Insertion","Base of the distal phalanx of the big toe"],["Action","Extends the big toe and dorsiflexes the foot"],["Innervation","Deep fibular nerve (L4–L5)"]]],["Extensor indicis","Upper limb: forearm (posterior)","Skeletal muscle. It extends the index finger (pointing).",[["Origin","Posterior surface of the ulna and interosseous membrane"],["Insertion","Extensor expansion of the index finger"],["Action","Extends the index finger (pointing)"],["Innervation","Posterior interosseous nerve (of the radial)"]]],["Extensor pollicis brevis","Upper limb: forearm (posterior)","Skeletal muscle. It extends the thumb at the metacarpophalangeal joint.",[["Origin","Posterior surface of the radius and interosseous membrane"],["Insertion","Base of the proximal phalanx of the thumb"],["Action","Extends the thumb at the metacarpophalangeal joint"],["Innervation","Posterior interosseous nerve (of the radial)"]]],["Extensor pollicis longus","Upper limb: forearm (posterior)","Skeletal muscle. It extends all the joints of the thumb.",[["Origin","Posterior surface of the ulna and interosseous membrane"],["Insertion","Base of the distal phalanx of the thumb"],["Action","Extends all the joints of the thumb"],["Innervation","Posterior interosseous nerve (of the radial)"]]],["External anal sphincter","Pelvis: pelvic floor","Ring of skeletal muscle under voluntary control that closes the anal canal.",[["Origin","Surrounds the anal canal (fibres of perianal skin, perineal body and anococcygeal ligament)"],["Insertion","Perineal body and anococcygeal ligament"],["Action","Voluntary closure of the anus (continence)"],["Innervation","Inferior rectal nerves (from the pudendal, S2–S4)"]]],["External iliac artery","Major arteries (pelvis)","It runs along the pelvic brim and, passing under the inguinal ligament, becomes the femoral artery, the main artery of the lower limb.",[]],["External iliac vein","Major veins (pelvis)","Continuation of the femoral vein above the inguinal ligament; it drains the lower limb.",[]],["External intercostal muscles","Thorax","Skeletal muscle. They elevate the ribs during inspiration.",[["Origin","Inferior border of the rib above"],["Insertion","Superior border of the rib below (fibres running downward and forward)"],["Action","Elevate the ribs during inspiration"],["Innervation","Intercostal nerves (T1–T11)"]]],["External oblique","Abdomen","The most superficial and largest of the broad muscles of the abdomen; its lower border forms the inguinal ligament.",[["Origin","External surfaces of ribs 5–12"],["Insertion","Linea alba, pubic tubercle and anterior half of the iliac crest"],["Action","Flexes and rotates the trunk to the opposite side; compresses the abdomen"],["Innervation","Thoracoabdominal nerves T7–T11 and subcostal nerve"]]],["Eyeballs","Sense organs","Organ of vision, spherical, ≈24 mm in diameter. It has three layers: fibrous (sclera and cornea), vascular (choroid, ciliary body and iris) and inner (retina). The lens and the cornea focus light on the retina.",[["Diameter","≈24 mm"],["Layers","Fibrous · vascular (uvea) · retina"]]],["Femur","Lower limb","Bone of the thigh; it is the longest, heaviest and strongest bone in the body (≈1/4 of body height). Its head articulates with the acetabulum and its condyles with the tibia and the patella.",[["Type","Long bone"],["Joints","Hip and knee"]]],["Fibula","Lower limb","Lateral, slender bone of the leg. It bears hardly any weight, but gives attachment to muscles and its distal end forms the lateral malleolus, which stabilises the ankle.",[["Type","Long bone"]]],["Fibularis (peroneus) brevis","Lower limb: leg (lateral)","Skeletal muscle. It everts the foot.",[["Origin","Lower two thirds of the lateral surface of the fibula"],["Insertion","Tuberosity of the fifth metatarsal"],["Action","Everts the foot"],["Innervation","Superficial fibular nerve (L5–S1)"]]],["Fibularis (peroneus) longus","Lower limb: leg (lateral)","Skeletal muscle. It everts the foot, helps in plantar flexion and supports the transverse arch.",[["Origin","Head and upper two thirds of the lateral surface of the fibula"],["Insertion","Base of the first metatarsal and medial cuneiform (crossing the sole)"],["Action","Everts the foot, helps in plantar flexion and supports the transverse arch"],["Innervation","Superficial fibular nerve (L5–S1)"]]],["Fibularis (peroneus) tertius","Lower limb: leg (anterior)","Skeletal muscle. Dorsiflexion and eversion of the foot.",[["Origin","Distal third of the fibula"],["Insertion","Base of the fifth metatarsal (dorsal)"],["Action","Dorsiflexion and eversion of the foot"],["Innervation","Deep fibular nerve (L4–L5)"]]],["C5 vertebra","Vertebral column","Typical cervical vertebra: small body, transverse foramina through which the vertebral artery ascends (C1–C6) and a short spinous process, bifid in C3–C6.",[]],["Fifth costal cartilage","Thoracic cage","Hyaline cartilage that joins the anterior end of the rib to the sternum. Its elasticity allows the thoracic cage to expand during breathing.",[]],["L5 vertebra","Vertebral column","Lumbar vertebra: the largest, with a kidney-shaped, robust body adapted to bear the weight of the trunk. Its spinous processes are short and horizontal. It articulates with the sacrum at the lumbosacral joint; the L5–S1 disc is one of those most affected by herniation.",[]],["Fifth metacarpal","Hand: metacarpus","Long bone of the palm of the hand. Its base articulates with the carpus and its head with the proximal phalanx (knuckle). Metacarpal of the little finger.",[]],["Fifth metatarsal","Foot: metatarsus","Long bone of the forefoot. Its base articulates with the tarsus and its head with the proximal phalanx; the metatarsal heads rest on the ground during walking. Its tuberosity receives the tendon of the fibularis brevis.",[]],["Fifth rib","Thoracic cage","True rib (vertebrosternal): it joins the sternum directly through its own costal cartilage.",[["No.","5th of 12 pairs"]]],["T5 vertebra","Vertebral column","Thoracic vertebra: it has costal facets on the body and on the transverse processes to articulate with the ribs, and a long spinous process pointing downward.",[]],["First costal cartilage","Thoracic cage","Hyaline cartilage that joins the anterior end of the rib to the sternum. Its elasticity allows the thoracic cage to expand during breathing.",[]],["L1 vertebra","Vertebral column","Lumbar vertebra: the largest, with a kidney-shaped, robust body adapted to bear the weight of the trunk. Its spinous processes are short and horizontal.",[]],["First lumbrical of the foot","Lower limb: foot (sole, 2nd layer)","Skeletal muscle. It flexes the metatarsophalangeal joint and extends the interphalangeal joints.",[["Origin","Tendons of the flexor digitorum longus"],["Insertion","Extensor expansion of the second toe"],["Action","Flexes the metatarsophalangeal joint and extends the interphalangeal joints"],["Innervation","Medial plantar nerve (S2–S3)"]]],["First metacarpal","Hand: metacarpus","Long bone of the palm of the hand. Its base articulates with the carpus and its head with the proximal phalanx (knuckle). Metacarpal of the thumb; the shortest and most robust, with great mobility.",[]],["First metatarsal","Foot: metatarsus","Long bone of the forefoot. Its base articulates with the tarsus and its head with the proximal phalanx; the metatarsal heads rest on the ground during walking. It is the shortest and thickest; it bears the greatest load.",[]],["First plantar interosseous","Lower limb: foot (sole, 4th layer)","Skeletal muscle. It adducts the toe toward the axis of the second toe.",[["Origin","Medial surface of the third metatarsal"],["Insertion","Base of the proximal phalanx of the third toe (medial side)"],["Action","Adducts the toe toward the axis of the second toe"],["Innervation","Lateral plantar nerve (S2–S3)"]]],["First rib","Thoracic cage","True rib (vertebrosternal): it joins the sternum directly through its own costal cartilage. It is the shortest, widest and flattest; the subclavian artery and vein cross its upper surface.",[["No.","1st of 12 pairs"]]],["T1 vertebra","Vertebral column","Thoracic vertebra: it has costal facets on the body and on the transverse processes to articulate with the ribs, and a long spinous process pointing downward. It articulates with the first rib and part of the second.",[]],["Quadratus plantae (flexor accessorius)","Lower limb: foot (sole, 2nd layer)","Skeletal muscle. It corrects the oblique pull of the flexor digitorum longus.",[["Origin","Medial and lateral surfaces of the calcaneus"],["Insertion","Lateral border of the tendon of the flexor digitorum longus"],["Action","Corrects the oblique pull of the flexor digitorum longus"],["Innervation","Lateral plantar nerve (S2–S3)"]]],["Flexor carpi radialis","Upper limb: forearm (anterior)","Skeletal muscle. It flexes and abducts the wrist.",[["Origin","Medial epicondyle of the humerus"],["Insertion","Base of the second metacarpal"],["Action","Flexes and abducts the wrist"],["Innervation","Median nerve (C6–C8)"]]],["Flexor digiti minimi brevis (foot)","Lower limb: foot (sole, 3rd layer)","Skeletal muscle. It flexes the fifth toe.",[["Origin","Base of the fifth metatarsal"],["Insertion","Base of the proximal phalanx of the fifth toe"],["Action","Flexes the fifth toe"],["Innervation","Lateral plantar nerve (S2–S3)"]]],["Flexor digiti minimi brevis (hand)","Upper limb: hand (hypothenar eminence)","Skeletal muscle. It flexes the little finger.",[["Origin","Hook of the hamate and flexor retinaculum"],["Insertion","Base of the proximal phalanx of the fifth toe"],["Action","Flexes the little finger"],["Innervation","Ulnar nerve (deep branch)"]]],["Flexor digitorum brevis","Lower limb: foot (sole, 1st layer)","Skeletal muscle. It flexes the 2nd–5th fingers.",[["Origin","Calcaneal tuberosity and plantar aponeurosis"],["Insertion","Middle phalanges of toes 2–5"],["Action","Flexes toes 2–5"],["Innervation","Medial plantar nerve (S2–S3)"]]],["Flexor digitorum longus","Lower limb: leg (posterior)","Skeletal muscle. It flexes the 2nd–5th toes and helps in plantar flexion.",[["Origin","Posterior surface of the tibia"],["Insertion","Bases of the distal phalanges of toes 2–5"],["Action","Flexes toes 2–5 and helps in plantar flexion"],["Innervation","Tibial nerve (S1–S2)"]]],["Flexor digitorum profundus","Upper limb: forearm (anterior)","Skeletal muscle. Only flexor of the distal interphalangeal joints.",[["Origin","Anterior and medial surfaces of the ulna and interosseous membrane"],["Insertion","Bases of the distal phalanges of toes 2–5"],["Action","Only flexor of the distal interphalangeal joints"],["Innervation","Median nerve (anterior interosseous; fingers 2–3) and ulnar nerve (fingers 4–5)"]]],["Flexor hallucis longus","Lower limb: leg (posterior)","Skeletal muscle. It flexes the big toe (push-off during walking).",[["Origin","Lower two thirds of the posterior surface of the fibula"],["Insertion","Base of the distal phalanx of the big toe"],["Action","Flexes the big toe (push-off during walking)"],["Innervation","Tibial nerve (S1–S2)"]]],["Flexor pollicis longus","Upper limb: forearm (anterior)","Skeletal muscle. It flexes the thumb.",[["Origin","Anterior surface of the radius and interosseous membrane"],["Insertion","Base of the distal phalanx of the thumb"],["Action","Flexes the thumb"],["Innervation","Anterior interosseous nerve (of the median)"]]],["Flexor retinaculum of the wrist","Upper limb: hand","Fibrous band that crosses the palmar side of the carpus and turns the carpal groove into the carpal tunnel, through which the median nerve and the flexor tendons pass. Its compression causes carpal tunnel syndrome.",[]],["Fornix","Brain: white matter","Arched bundle of fibres that is the main output pathway of the hippocampus; it ends mostly in the mammillary bodies. It takes part in memory circuits (Papez circuit).",[]],["C4 vertebra","Vertebral column","Typical cervical vertebra: small body, transverse foramina through which the vertebral artery ascends (C1–C6) and a short spinous process, bifid in C3–C6.",[]],["Fourth costal cartilage","Thoracic cage","Hyaline cartilage that joins the anterior end of the rib to the sternum. Its elasticity allows the thoracic cage to expand during breathing.",[]],["L4 vertebra","Vertebral column","Lumbar vertebra: the largest, with a kidney-shaped, robust body adapted to bear the weight of the trunk. Its spinous processes are short and horizontal.",[]],["Fourth lumbrical of the foot","Lower limb: foot (sole, 2nd layer)","Skeletal muscle. It flexes the metatarsophalangeal joint and extends the interphalangeal joints.",[["Origin","Tendons of the flexor digitorum longus"],["Insertion","Extensor expansion of the fifth finger"],["Action","Flexes the metatarsophalangeal joint and extends the interphalangeal joints"],["Innervation","Lateral plantar nerve (S2–S3)"]]],["Fourth metacarpal","Hand: metacarpus","Long bone of the palm of the hand. Its base articulates with the carpus and its head with the proximal phalanx (knuckle). Metacarpal of the ring finger.",[]],["Fourth metatarsal","Foot: metatarsus","Long bone of the forefoot. Its base articulates with the tarsus and its head with the proximal phalanx; the metatarsal heads rest on the ground during walking.",[]],["Fourth rib","Thoracic cage","True rib (vertebrosternal): it joins the sternum directly through its own costal cartilage.",[["No.","4th of 12 pairs"]]],["T4 vertebra","Vertebral column","Thoracic vertebra: it has costal facets on the body and on the transverse processes to articulate with the ribs, and a long spinous process pointing downward.",[]],["Fourth ventricle","Brain: ventricular system","Rhomboid cavity between the brainstem and the cerebellum. Its openings (median and lateral) release cerebrospinal fluid into the subarachnoid space.",[]],["Free taenia of the colon","Digestive tract","One of the three longitudinal bands of smooth muscle of the colon; it is visible on the anterior surface of the ascending and descending colon.",[]],["Frontal bone","Skull","Unpaired bone that forms the forehead, the roof of the orbits and the anterior part of the cranial vault. It contains the frontal sinuses.",[["Type","Flat bone"],["Articulates with","Parietals, sphenoid, ethmoid, nasals, maxillae, lacrimals and zygomatics"]]],["Frontalis (frontal belly of occipitofrontalis)","Head: muscles of facial expression","Skeletal muscle. It elevates the eyebrows and wrinkles the forehead horizontally.",[["Origin","Epicranial aponeurosis"],["Insertion","Skin of the eyebrow and forehead"],["Action","Elevates the eyebrows and wrinkles the forehead horizontally"],["Innervation","Facial nerve (VII), temporal branches"]]],["Fusiform gyrus (lateral occipitotemporal)","Brain: cerebral cortex","Gyrus of the cerebral cortex (grey matter). On the inferior surface of the hemisphere. It contains the fusiform face area and the visual word form area.",[["Lobe","Temporal / occipital"]]],["Gallbladder","Accessory glands","Pear-shaped sac under the liver that stores and concentrates bile (≈30–50 ml). It empties it into the duodenum after fatty meals under the action of cholecystokinin.",[["Capacity","≈30–50 ml"]]],["Inferior gemellus","Lower limb: hip and gluteal region (lateral rotators)","Skeletal muscle. It laterally rotates the thigh.",[["Origin","Ischial tuberosity"],["Insertion","Greater trochanter (with the tendon of the obturator internus)"],["Action","Laterally rotates the thigh"],["Innervation","Nerve to the quadratus femoris (L5–S1)"]]],["Superior gemellus","Lower limb: hip and gluteal region (lateral rotators)","Skeletal muscle. It laterally rotates the thigh.",[["Origin","Ischial spine"],["Insertion","Greater trochanter (with the tendon of the obturator internus)"],["Action","Laterally rotates the thigh"],["Innervation","Nerve to the obturator internus (L5–S1)"]]],["Geniohyoid","Neck (suprahyoid)","Skeletal muscle. It pulls the hyoid forward and up; it depresses the mandible.",[["Origin","Inferior mental spine of the mandible"],["Insertion","Body of the hyoid"],["Action","Pulls the hyoid forward and up; depresses the mandible"],["Innervation","C1 via the hypoglossal nerve (XII)"]]],["Lower gingiva","Mouth and teeth","Fibrous mucosa that covers the alveolar part of the mandible and surrounds the neck of the teeth.",[]],["Upper gingiva","Mouth and teeth","Fibrous mucosa that covers the alveolar processes of the maxilla and surrounds the neck of the teeth.",[]],["Glans penis","Male reproductive system","Expanded distal end of the corpus spongiosum; it contains the external urethral orifice and abundant sensory endings.",[]],["Globus pallidus","Brain: deep nuclei","Medial part of the lentiform nucleus. It is the main output of the basal ganglia to the thalamus; its function is inhibitory.",[["Group","Basal ganglia"]]],["Gluteus maximus","Lower limb: hip and gluteal region","The bulkiest muscle in the body. It extends the hip and laterally rotates it.",[["Origin","Posterior surface of the ilium, sacrum, coccyx and sacrotuberous ligament"],["Insertion","Iliotibial tract and gluteal tuberosity of the femur"],["Action","Powerful extensor of the hip (standing up, climbing stairs); lateral rotation"],["Innervation","Inferior gluteal nerve (L5–S2)"]]],["Gluteus medius","Lower limb: hip and gluteal region","Its weakness produces the Trendelenburg sign (drop of the pelvis on the opposite side when standing on that leg).",[["Origin","External surface of the ilium, between the anterior and posterior gluteal lines"],["Insertion","Lateral surface of the greater trochanter"],["Action","Abducts and medially rotates the thigh; stabilises the pelvis when walking"],["Innervation","Superior gluteal nerve (L4–S1)"]]],["Gluteus minimus","Lower limb: hip and gluteal region","Skeletal muscle. It abducts and medially rotates the thigh; it stabilises the pelvis.",[["Origin","External surface of the ilium, between the anterior and inferior gluteal lines"],["Insertion","Anterior surface of the greater trochanter"],["Action","Abducts and medially rotates the thigh; stabilises the pelvis"],["Innervation","Superior gluteal nerve (L4–S1)"]]],["Gracilis","Lower limb: thigh (medial)","Skeletal muscle. It adducts the thigh and flexes the knee.",[["Origin","Body and inferior ramus of the pubis"],["Insertion","Medial surface of the upper tibia (pes anserinus)"],["Action","Adducts the thigh and flexes the knee"],["Innervation","Obturator nerve (L2–L4)"]]],["Great cardiac vein","Heart: cardiac veins","It ascends in the anterior interventricular groove alongside the anterior interventricular artery and drains into the coronary sinus.",[]],["Habenula","Brain: deep nuclei","Small nucleus of the epithalamus, next to the pineal gland. It takes part in the response to negative reward and aversion.",[["Group","Epithalamus"]]],["Hamate","Hand: carpus","Short bone of the carpus. The eight carpal bones are arranged in two rows and form the skeleton of the wrist. Distal row; its hook bounds Guyon's canal, through which the ulnar nerve and artery pass.",[]],["Hip bone","Pelvis","Paired bone formed by the fusion of the ilium, ischium and pubis, which converge at the acetabulum, where the head of the femur sits. With the sacrum and coccyx it forms the bony pelvis.",[["Parts","Ilium, ischium and pubis"],["Joints","Sacroiliac, pubic symphysis and hip joint"]]],["Hippocampus","Brain: deep nuclei","Curved structure of the medial temporal lobe, in the floor of the temporal horn of the lateral ventricle. Essential for forming new declarative memories and for spatial memory; one of the first regions affected in Alzheimer's disease.",[["Group","Limbic system"]]],["Extensor carpi ulnaris — humeral head","Upper limb: forearm (posterior)","Skeletal muscle. It extends and adducts the wrist.",[["Origin","Lateral epicondyle of the humerus"],["Insertion","Base of the fifth metacarpal"],["Action","Extends and adducts the wrist"],["Innervation","Posterior interosseous nerve (of the radial)"]]],["Flexor carpi ulnaris — humeral head","Upper limb: forearm (anterior)","Skeletal muscle. It flexes and adducts the wrist.",[["Origin","Medial epicondyle of the humerus"],["Insertion","Pisiform, hook of the hamate and fifth metacarpal"],["Action","Flexes and adducts the wrist"],["Innervation","Ulnar nerve (C7–T1)"]]],["Pronator teres — humeral head","Upper limb: forearm (anterior)","Skeletal muscle. It pronates the forearm and flexes the elbow.",[["Origin","Medial epicondyle of the humerus"],["Insertion","Lateral surface of the radius (middle third)"],["Action","Pronates the forearm and flexes the elbow"],["Innervation","Median nerve (C6–C8)"]]],["Flexor digitorum superficialis — humeroulnar head","Upper limb: forearm (anterior)","Skeletal muscle. It flexes the proximal interphalangeal joints and the wrist.",[["Origin","Medial epicondyle of the humerus and coronoid process of the ulna"],["Insertion","Middle phalanges of toes 2–5"],["Action","Flexes the proximal interphalangeal joints and the wrist"],["Innervation","Median nerve (C6–C8)"]]],["Humerus","Upper limb","Long bone of the arm. Its head articulates with the scapula (shoulder) and its distal end with the radius and ulna (elbow). The radial nerve runs in its groove on the shaft.",[["Type","Long bone"],["Joints","Glenohumeral and elbow"]]],["Hyoid bone","Neck","U-shaped bone located in the neck at the level of C3. It is the only bone that does not articulate with any other: it is suspended by muscles and ligaments and serves as an anchor for the tongue.",[["Parts","Body, greater horns and lesser horns"]]],["Hypothalamus","Brain: deep nuclei","Region of the diencephalon below the thalamus. It controls the autonomic nervous system and the pituitary gland, and regulates temperature, hunger, thirst, sleep and circadian rhythms.",[["Group","Diencephalon"],["Weight","≈4 g"]]],["Ileum","Digestive tract","Final part of the small intestine (distal ≈3/5). It absorbs vitamin B12 and bile salts and contains Peyer's patches (lymphoid tissue). It opens into the caecum through the ileocecal valve.",[["Length","≈3.5 m"]]],["Iliacus","Lower limb: hip and gluteal region","Skeletal muscle. It flexes the thigh at the hip.",[["Origin","Iliac fossa"],["Insertion","Lesser trochanter of the femur (with the psoas)"],["Action","Flexes the thigh at the hip"],["Innervation","Femoral nerve (L2–L3)"]]],["Iliococcygeus","Pelvis: pelvic floor (levator ani)","Skeletal muscle. It supports the pelvic viscera.",[["Origin","Tendinous arch of the levator ani and ischial spine"],["Insertion","Coccyx and anococcygeal ligament"],["Action","Supports the pelvic viscera"],["Innervation","Nerve to the levator ani (S4)"]]],["Iliocostalis cervicis","Back: deep muscles (erector spinae)","Skeletal muscle. It extends and laterally tilts the neck.",[["Origin","Angles of ribs 3–6"],["Insertion","Transverse processes of C4–C6"],["Action","Extends and laterally tilts the neck"],["Innervation","Posterior rami of the spinal nerves"]]],["Iliocostalis lumborum","Back: deep muscles (erector spinae)","Skeletal muscle. It extends and laterally tilts the spine.",[["Origin","Iliac crest, sacrum and thoracolumbar fascia"],["Insertion","Angles of ribs 6–12"],["Action","Extends and laterally tilts the spine"],["Innervation","Posterior rami of the spinal nerves"]]],["Iliocostalis thoracis","Back: deep muscles (erector spinae)","Skeletal muscle. It extends and laterally tilts the spine.",[["Origin","Angles of ribs 7–12"],["Insertion","Angles of ribs 1–6 and transverse process of C7"],["Action","Extends and laterally tilts the spine"],["Innervation","Posterior rami of the spinal nerves"]]],["Iliotibial tract","Lower limb: hip and gluteal region","Lateral thickening of the fascia lata that extends from the iliac crest to the lateral condyle of the tibia (Gerdy's tubercle). It receives the tensor fasciae latae and the gluteus maximus and stabilises the hip and knee.",[]],["Inferior colliculus","Brain: brainstem and cerebellum","Eminence of the roof of the midbrain that is an obligatory relay of the auditory pathway and takes part in sound localisation.",[["Pathway","Auditory"]]],["Inferior mesenteric artery","Major arteries (abdominal)","It arises from the aorta at L3 and supplies the distal third of the transverse colon, the descending colon, the sigmoid and the upper rectum.",[]],["Inferior nasal concha","Skull","Paired, curved bone on the lateral wall of the nasal cavity. It increases the surface of the mucosa that warms and humidifies inspired air.",[]],["Longus colli — inferior oblique part","Neck (prevertebral)","Skeletal muscle. It flexes and tilts the neck.",[["Origin","Vertebral bodies of T1–T3"],["Insertion","Anterior tubercles of the transverse processes of C5–C6"],["Action","Flexes and tilts the neck"],["Innervation","Anterior rami of C2–C6"]]],["Inferior temporal gyrus","Brain: cerebral cortex","Gyrus of the cerebral cortex (grey matter). Part of the ventral visual pathway (\"what\"): recognition of objects and shapes.",[["Lobe","Temporal"]]],["Inferior vena cava","Major veins","The largest vein in the body. It forms at L5 by the union of the common iliac veins, ascends to the right of the aorta, crosses the diaphragm (T8) and drains into the right atrium.",[]],["Infraspinatus","Upper limb: shoulder (rotator cuff)","Skeletal muscle. It laterally rotates the arm and stabilises the shoulder.",[["Origin","Infraspinous fossa of the scapula"],["Insertion","Middle facet of the greater tubercle of the humerus"],["Action","Laterally rotates the arm and stabilises the shoulder"],["Innervation","Suprascapular nerve (C5–C6)"]]],["Inguinal ligament","Abdomen","Fibrous band that extends from the anterior superior iliac spine to the pubic tubercle. It is the thickened lower border of the external oblique aponeurosis and marks the boundary between abdomen and thigh.",[["Insertions","Anterior superior iliac spine → pubic tubercle"]]],["Innermost intercostal muscles","Thorax","Skeletal muscle. They act together with the internal intercostals.",[["Origin","Inner surface of the rib below"],["Insertion","Inner surface of the rib above"],["Action","They act together with the internal intercostals"],["Innervation","Intercostal nerves (T1–T11)"]]],["Insula","Brain: cerebral cortex","Lobe of the cerebral cortex hidden in the depth of the lateral sulcus, covered by the frontal, parietal and temporal opercula. It processes taste, interoception (visceral sensations), pain and emotional awareness.",[["Lobe","Insular"]]],["Intermediate cuneiform","Foot: tarsus","Short bone of the tarsus. The seven tarsal bones form the posterior skeleton of the foot. The smallest of the cuneiforms; it articulates with the second metatarsal.",[]],["Intermediate tendon of the digastric","Neck (suprahyoid)","Tendon that joins the anterior and posterior bellies of the digastric. It passes through the stylohyoid and is attached to the hyoid by a fibrous loop.",[]],["Internal iliac artery","Major arteries (pelvis)","It supplies the pelvic viscera, the perineum, the gluteal region and the medial part of the thigh.",[]],["Internal iliac vein","Major veins (pelvis)","It drains the pelvic viscera, the perineum and the gluteal region.",[]],["Internal intercostal muscles","Thorax","Skeletal muscle. They lower the ribs during forced expiration.",[["Origin","Superior border of the rib below"],["Insertion","Inferior border of the rib above (fibres perpendicular to the external ones)"],["Action","Lower the ribs during forced expiration"],["Innervation","Intercostal nerves (T1–T11)"]]],["Internal jugular vein","Major veins","It collects blood from the brain, face and neck. It arises at the jugular foramen and descends in the carotid sheath alongside the carotid artery and the vagus nerve.",[]],["Internal oblique","Abdomen","Skeletal muscle. It flexes and rotates the trunk to the same side; it compresses the abdomen.",[["Origin","Thoracolumbar fascia, iliac crest and lateral two thirds of the inguinal ligament"],["Insertion","Ribs 10–12, linea alba and pubis (conjoint tendon)"],["Action","Flexes and rotates the trunk to the same side; compresses the abdomen"],["Innervation","Thoracoabdominal, iliohypogastric and ilioinguinal nerves (T7–L1)"]]],["Interosseous membrane of the forearm","Upper limb: forearm (posterior)","Fibrous sheet that joins the interosseous borders of the radius and ulna. It transmits forces from the radius to the ulna and gives origin to deep muscles of the forearm.",[["Type","Syndesmosis (fibrous joint)"]]],["Interosseous membrane of the leg","Lower limb: leg (posterior)","Fibrous sheet that joins the interosseous borders of the tibia and fibula. It separates the anterior and posterior compartments of the leg and gives origin to muscles.",[]],["Interpeduncular fossa","Brain: brainstem and cerebellum","Depression between the two cerebral peduncles, on the anterior surface of the midbrain, from which the oculomotor nerve (III) emerges.",[]],["Interventricular foramen (of Monro)","Brain: ventricular system","Opening that connects each lateral ventricle with the third ventricle.",[]],["Intervertebral disc C2–C3","Vertebral column","Intervertebral disc: fibrocartilage formed by a peripheral fibrous ring and a central gelatinous nucleus pulposus. It absorbs loads and allows small movements between vertebrae.",[]],["Intervertebral disc T8–T9","Vertebral column","Intervertebral disc: fibrocartilage formed by a peripheral fibrous ring and a central gelatinous nucleus pulposus. It absorbs loads and allows small movements between vertebrae.",[]],["Intervertebral disc T11–T12","Vertebral column","Intervertebral disc: fibrocartilage formed by a peripheral fibrous ring and a central gelatinous nucleus pulposus. It absorbs loads and allows small movements between vertebrae.",[]],["Intervertebral disc C5–C6","Vertebral column","Intervertebral disc: fibrocartilage formed by a peripheral fibrous ring and a central gelatinous nucleus pulposus. It absorbs loads and allows small movements between vertebrae.",[]],["Intervertebral disc L5–S1","Vertebral column","Intervertebral disc: fibrocartilage formed by a peripheral fibrous ring and a central gelatinous nucleus pulposus. It absorbs loads and allows small movements between vertebrae.",[]],["Intervertebral disc T5–T6","Vertebral column","Intervertebral disc: fibrocartilage formed by a peripheral fibrous ring and a central gelatinous nucleus pulposus. It absorbs loads and allows small movements between vertebrae.",[]],["Intervertebral disc L1–L2","Vertebral column","Intervertebral disc: fibrocartilage formed by a peripheral fibrous ring and a central gelatinous nucleus pulposus. It absorbs loads and allows small movements between vertebrae.",[]],["Intervertebral disc T1–T2","Vertebral column","Intervertebral disc: fibrocartilage formed by a peripheral fibrous ring and a central gelatinous nucleus pulposus. It absorbs loads and allows small movements between vertebrae.",[]],["Intervertebral disc C4–C5","Vertebral column","Intervertebral disc: fibrocartilage formed by a peripheral fibrous ring and a central gelatinous nucleus pulposus. It absorbs loads and allows small movements between vertebrae.",[]],["Intervertebral disc L4–L5","Vertebral column","Intervertebral disc: fibrocartilage formed by a peripheral fibrous ring and a central gelatinous nucleus pulposus. It absorbs loads and allows small movements between vertebrae.",[]],["Intervertebral disc T4–T5","Vertebral column","Intervertebral disc: fibrocartilage formed by a peripheral fibrous ring and a central gelatinous nucleus pulposus. It absorbs loads and allows small movements between vertebrae.",[]],["Intervertebral disc T9–T10","Vertebral column","Intervertebral disc: fibrocartilage formed by a peripheral fibrous ring and a central gelatinous nucleus pulposus. It absorbs loads and allows small movements between vertebrae.",[]],["Intervertebral disc L2–L3","Vertebral column","Intervertebral disc: fibrocartilage formed by a peripheral fibrous ring and a central gelatinous nucleus pulposus. It absorbs loads and allows small movements between vertebrae.",[]],["Intervertebral disc T2–T3","Vertebral column","Intervertebral disc: fibrocartilage formed by a peripheral fibrous ring and a central gelatinous nucleus pulposus. It absorbs loads and allows small movements between vertebrae.",[]],["Intervertebral disc C7–T1","Vertebral column","Intervertebral disc: fibrocartilage formed by a peripheral fibrous ring and a central gelatinous nucleus pulposus. It absorbs loads and allows small movements between vertebrae.",[]],["Intervertebral disc T7–T8","Vertebral column","Intervertebral disc: fibrocartilage formed by a peripheral fibrous ring and a central gelatinous nucleus pulposus. It absorbs loads and allows small movements between vertebrae.",[]],["Intervertebral disc C6–C7","Vertebral column","Intervertebral disc: fibrocartilage formed by a peripheral fibrous ring and a central gelatinous nucleus pulposus. It absorbs loads and allows small movements between vertebrae.",[]],["Intervertebral disc T6–T7","Vertebral column","Intervertebral disc: fibrocartilage formed by a peripheral fibrous ring and a central gelatinous nucleus pulposus. It absorbs loads and allows small movements between vertebrae.",[]],["Intervertebral disc T10–T11","Vertebral column","Intervertebral disc: fibrocartilage formed by a peripheral fibrous ring and a central gelatinous nucleus pulposus. It absorbs loads and allows small movements between vertebrae.",[]],["Intervertebral disc C3–C4","Vertebral column","Intervertebral disc: fibrocartilage formed by a peripheral fibrous ring and a central gelatinous nucleus pulposus. It absorbs loads and allows small movements between vertebrae.",[]],["Intervertebral disc L3–L4","Vertebral column","Intervertebral disc: fibrocartilage formed by a peripheral fibrous ring and a central gelatinous nucleus pulposus. It absorbs loads and allows small movements between vertebrae.",[]],["Intervertebral disc T3–T4","Vertebral column","Intervertebral disc: fibrocartilage formed by a peripheral fibrous ring and a central gelatinous nucleus pulposus. It absorbs loads and allows small movements between vertebrae.",[]],["Intervertebral disc T12–L1","Vertebral column","Intervertebral disc: fibrocartilage formed by a peripheral fibrous ring and a central gelatinous nucleus pulposus. It absorbs loads and allows small movements between vertebrae.",[]],["Jejunum","Digestive tract","Second part of the small intestine (proximal ≈2/5 of the jejunoileum). It has tall, abundant circular folds and is the main site of nutrient absorption.",[["Length","≈2.5 m"]]],["Kidney","Urinary system","Bean-shaped retroperitoneal organ (≈11 cm) located between T12 and L3; the right one is slightly lower because of the liver. It filters ≈180 L of plasma per day through ≈1 million nephrons and produces 1–2 L of urine. It also secretes renin and erythropoietin.",[["Size","≈11 × 6 × 3 cm"],["Weight","≈150 g"],["Functional unit","Nephron"]]],["Lips","Mouth and teeth","Musculomembranous folds that surround the mouth opening, formed by the orbicularis oris muscle covered by skin and mucosa. Its red zone (vermilion) has a thin, highly vascularised epithelium.",[]],["Lacrimal bone","Skull","Paired bone, the smallest of the face, on the medial wall of the orbit. It contains the fossa for the lacrimal sac.",[]],["Lamina terminalis","Brain: white matter","Thin sheet that forms the anterior wall of the third ventricle. It contains the vascular organ, sensitive to blood osmolarity (thirst).",[]],["Lateral cuneiform","Foot: tarsus","Short bone of the tarsus. The seven tarsal bones form the posterior skeleton of the foot. It articulates with the third metatarsal and the cuboid.",[]],["Lateral geniculate body","Brain: deep nuclei","Thalamic nucleus that receives the optic tract and sends the optic radiation to the visual cortex. It is the relay of the visual pathway.",[["Group","Metathalamus"]]],["Flexor hallucis brevis — lateral head","Lower limb: foot (sole, 3rd layer)","Skeletal muscle. It flexes the big toe at the metatarsophalangeal joint.",[["Origin","Cuboid and lateral cuneiform"],["Insertion","Base of the proximal phalanx of the big toe (lateral side)"],["Action","Flexes the big toe at the metatarsophalangeal joint"],["Innervation","Medial plantar nerve (S2–S3)"]]],["Gastrocnemius — lateral head","Lower limb: leg (posterior) (triceps surae)","Skeletal muscle. Plantar flexion of the foot and flexion of the knee.",[["Origin","Lateral surface of the lateral condyle of the femur"],["Insertion","Calcaneal tuberosity via the calcaneal tendon"],["Action","Plantar flexion of the foot and flexion of the knee"],["Innervation","Tibial nerve (S1–S2)"]]],["Triceps brachii — lateral head","Upper limb: arm","Skeletal muscle. It extends the elbow.",[["Origin","Posterior surface of the humerus, above the radial groove"],["Insertion","Olecranon of the ulna"],["Action","Extends the elbow"],["Innervation","Radial nerve (C6–C8)"]]],["Lateral ventricle","Brain: ventricular system","C-shaped cavity inside each hemisphere, filled with cerebrospinal fluid. It communicates with the third ventricle through the interventricular foramen.",[["Parts","Frontal horn, body, atrium, occipital horn and temporal horn"]]],["Latissimus dorsi","Back: superficial muscles","The broadest muscle in the body. It extends, adducts and medially rotates the arm.",[["Origin","Spinous processes of T7–L5 (thoracolumbar fascia), iliac crest and ribs 9–12"],["Insertion","Intertubercular groove of the humerus"],["Action","Extends, adducts and medially rotates the humerus (climbing, rowing)"],["Innervation","Thoracodorsal nerve (C6–C8)"]]],["Levator anguli oris","Head: muscles of facial expression","Skeletal muscle. It elevates the angle of the mouth.",[["Origin","Canine fossa of the maxilla"],["Insertion","Angle of the mouth"],["Action","Elevates the angle of the mouth"],["Innervation","Facial nerve (VII), buccal branches"]]],["Levator labii superioris","Head: muscles of facial expression","Skeletal muscle. It elevates and everts the upper lip.",[["Origin","Infraorbital margin of the maxilla"],["Insertion","Skin of the upper lip"],["Action","Elevates and everts the upper lip"],["Innervation","Facial nerve (VII), zygomatic and buccal branches"]]],["Levator labii superioris alaeque nasi","Head: muscles of facial expression","Skeletal muscle. It elevates the upper lip and dilates the nostril.",[["Origin","Frontal process of the maxilla"],["Insertion","Alar cartilage and upper lip"],["Action","Elevates the upper lip and dilates the nostril"],["Innervation","Facial nerve (VII), zygomatic and buccal branches"]]],["Levator scapulae","Back: superficial muscles","Skeletal muscle. It elevates the scapula and tilts the neck.",[["Origin","Transverse processes of C1–C4"],["Insertion","Superior angle of the scapula"],["Action","Elevates the scapula and tilts the neck"],["Innervation","Dorsal scapular nerve (C5) and branches of C3–C4"]]],["Linea alba","Abdomen","Fibrous raphe of the anterior midline of the abdomen, from the xiphoid process to the pubic symphysis, formed by the interlacing of the aponeuroses of the broad muscles of the abdomen. It contains the umbilicus.",[["Type","Dense connective tissue"]]],["Liver","Accessory glands","The largest gland in the body (≈1.5 kg), located in the right hypochondrium under the diaphragm. It produces bile, metabolises nutrients and drugs, synthesises plasma proteins and stores glycogen. It receives blood from the hepatic artery and the portal vein.",[["Weight","≈1.4–1.6 kg"],["Blood supply","25 % arterial, 75 % portal"]]],["Lobe of the thymus","Lymphoid organs","Primary lymphoid organ of the anterior mediastinum, formed by two lobes. T lymphocytes mature in it. It is large in childhood and is progressively replaced by fat in adults (involution).",[["Function","T lymphocyte maturation"]]],["Biceps brachii — long head","Upper limb: arm","Lateral head of the biceps brachii. Its tendon crosses the shoulder joint through the intertubercular groove.",[["Origin","Supraglenoid tubercle of the scapula (intra-articular tendon)"],["Insertion","Radial tuberosity and bicipital aponeurosis"],["Action","Supinates the forearm and flexes the elbow; helps in shoulder flexion"],["Innervation","Musculocutaneous nerve (C5–C6)"]]],["Biceps femoris — long head","Lower limb: thigh (posterior, hamstrings)","Skeletal muscle. It flexes the knee and extends the hip; it laterally rotates the leg.",[["Origin","Ischial tuberosity"],["Insertion","Head of the fibula"],["Action","Flexes the knee and extends the hip; laterally rotates the leg"],["Innervation","Sciatic nerve, tibial part (L5–S2)"]]],["Triceps brachii — long head","Upper limb: arm","Head of the triceps brachii, the only muscle of the posterior compartment of the arm and the main extensor of the elbow.",[["Origin","Infraglenoid tubercle of the scapula"],["Insertion","Olecranon of the ulna"],["Action","Extends the elbow; extends and adducts the arm"],["Innervation","Radial nerve (C6–C8)"]]],["Long plantar ligament","Lower limb: foot","The longest ligament of the sole of the foot: it runs from the plantar surface of the calcaneus to the cuboid and the bases of metatarsals 2–5. It maintains the lateral longitudinal arch.",[]],["Longissimus capitis","Back: deep muscles (erector spinae)","Skeletal muscle. It extends the head and turns it to the same side.",[["Origin","Transverse processes of T1–T5 and articular processes of C4–C7"],["Insertion","Mastoid process"],["Action","Extends the head and turns it to the same side"],["Innervation","Posterior rami of the spinal nerves"]]],["Longissimus cervicis","Back: deep muscles (erector spinae)","Skeletal muscle. It extends and laterally tilts the neck.",[["Origin","Transverse processes of T1–T5"],["Insertion","Transverse processes of C2–C6"],["Action","Extends and laterally tilts the neck"],["Innervation","Posterior rami of the spinal nerves"]]],["Longissimus thoracis","Back: deep muscles (erector spinae)","Skeletal muscle. It extends and laterally tilts the spine.",[["Origin","Sacrum, lumbar spinous processes and lumbar transverse processes"],["Insertion","Thoracic transverse processes and ribs 2–12"],["Action","Extends and laterally tilts the spine"],["Innervation","Posterior rami of the spinal nerves"]]],["Longus capitis","Neck (prevertebral)","Skeletal muscle. It flexes the head.",[["Origin","Anterior tubercles of the transverse processes of C3–C6"],["Insertion","Basilar part of the occipital bone"],["Action","Flexes the head"],["Innervation","Anterior rami of C1–C3"]]],["Lower central incisor","Mouth and teeth","The smallest tooth of the permanent dentition; cutting crown and a single root. Teeth are part of the digestive system (oral cavity). Adults have 32 permanent teeth; in this model the third molars (wisdom teeth) are missing. They are made of enamel, dentin, pulp and cementum.",[]],["Lower first molar","Mouth and teeth","Molar with five cusps and two roots (mesial and distal). It erupts at about 6 years of age. Teeth are part of the digestive system (oral cavity). Adults have 32 permanent teeth; in this model the third molars (wisdom teeth) are missing. They are made of enamel, dentin, pulp and cementum.",[]],["Lower first premolar","Mouth and teeth","Premolar with one dominant buccal cusp and a small lingual one; one root. Teeth are part of the digestive system (oral cavity). Adults have 32 permanent teeth; in this model the third molars (wisdom teeth) are missing. They are made of enamel, dentin, pulp and cementum.",[]],["Lateral pterygoid — inferior head","Head: muscles of mastication","Skeletal muscle. It protrudes the mandible and starts opening the mouth; lateral movements.",[["Origin","Lateral surface of the lateral plate of the pterygoid process"],["Insertion","Pterygoid fovea of the neck of the mandibular condyle"],["Action","Protrudes the mandible and starts opening the mouth; lateral movements"],["Innervation","Mandibular nerve (V3), branch of the trigeminal"]]],["Lower lateral incisor","Mouth and teeth","Cutting tooth with a single root, somewhat larger than the lower central incisor. Teeth are part of the digestive system (oral cavity). Adults have 32 permanent teeth; in this model the third molars (wisdom teeth) are missing. They are made of enamel, dentin, pulp and cementum.",[]],["Lower second molar","Mouth and teeth","Molar with four cusps and two roots. It erupts at about 12 years of age. Teeth are part of the digestive system (oral cavity). Adults have 32 permanent teeth; in this model the third molars (wisdom teeth) are missing. They are made of enamel, dentin, pulp and cementum.",[]],["Lower second premolar","Mouth and teeth","Premolar with two or three cusps; one root. Teeth are part of the digestive system (oral cavity). Adults have 32 permanent teeth; in this model the third molars (wisdom teeth) are missing. They are made of enamel, dentin, pulp and cementum.",[]],["Lower canine","Mouth and teeth","Tooth with a pointed cusp that tears food; a single long root. Teeth are part of the digestive system (oral cavity). Adults have 32 permanent teeth; in this model the third molars (wisdom teeth) are missing. They are made of enamel, dentin, pulp and cementum.",[]],["Lumbar rotator muscles","Back: deep muscles (erector spinae) (transversospinal)","Skeletal muscle. They stabilise and rotate the spine; proprioceptive function.",[["Origin","Mammillary processes of the lumbar vertebrae"],["Insertion","Lamina or spinous process of the vertebra above"],["Action","Stabilise and rotate the spine; proprioceptive function"],["Innervation","Posterior rami of the spinal nerves"]]],["Lunate","Hand: carpus","Short bone of the carpus. The eight carpal bones are arranged in two rows and form the skeleton of the wrist. Proximal row; it is the carpal bone that dislocates most frequently.",[]],["Mammillary body","Brain: deep nuclei","Pair of small rounded eminences at the base of the hypothalamus. They receive the fornix and are part of the memory circuit; they are damaged in Wernicke-Korsakoff syndrome.",[["Group","Diencephalon"]]],["Mandible","Skull","The only movable bone of the skull and the strongest of the face. It houses the lower teeth and articulates with the temporal bones at the temporomandibular joints.",[["Parts","Body, rami, coronoid processes and condyles"],["Joint","Temporomandibular (bicondylar)"]]],["Manubrium of the sternum","Thoracic cage","Upper part of the sternum. It articulates with the clavicles and the first costal cartilage; its junction with the body forms the sternal angle (of Louis), at the level of the second rib.",[]],["Maxilla","Skull","Paired bone that forms the upper jaw, part of the hard palate, the floor of the orbit and the lateral wall of the nasal cavities. It houses the upper teeth and the maxillary sinus.",[["Type","Pneumatic bone"],["Contains","Maxillary sinus and upper dental alveoli"]]],["Medial cuneiform","Foot: tarsus","Short bone of the tarsus. The seven tarsal bones form the posterior skeleton of the foot. The largest of the three cuneiforms; it articulates with the first metatarsal.",[]],["Medial geniculate body","Brain: deep nuclei","Thalamic nucleus that relays the auditory pathway: it receives fibres from the inferior colliculus and projects to the auditory cortex.",[["Group","Metathalamus"]]],["Flexor hallucis brevis — medial head","Lower limb: foot (sole, 3rd layer)","Skeletal muscle. It flexes the big toe at the metatarsophalangeal joint.",[["Origin","Cuboid and lateral cuneiform"],["Insertion","Base of the proximal phalanx of the big toe (medial side)"],["Action","Flexes the big toe at the metatarsophalangeal joint"],["Innervation","Medial plantar nerve (S2–S3)"]]],["Gastrocnemius — medial head","Lower limb: leg (posterior) (triceps surae)","Medial head of the \"twins\" (gastrocnemius), which form the bulge of the calf.",[["Origin","Popliteal surface of the femur, above the medial condyle"],["Insertion","Calcaneal tuberosity via the calcaneal tendon"],["Action","Plantar flexion of the foot and flexion of the knee"],["Innervation","Tibial nerve (S1–S2)"]]],["Triceps brachii — medial head","Upper limb: arm","Skeletal muscle. It extends the elbow.",[["Origin","Posterior surface of the humerus, below the radial groove"],["Insertion","Olecranon of the ulna"],["Action","Extends the elbow"],["Innervation","Radial nerve (C6–C8)"]]],["Medial pterygoid","Head: muscles of mastication","Skeletal muscle. It elevates the mandible and, together with the lateral pterygoid, produces lateral movements.",[["Origin","Pterygoid fossa (medial surface of the lateral plate of the pterygoid process)"],["Insertion","Medial surface of the angle of the mandible"],["Action","Elevates the mandible and, together with the lateral pterygoid, produces lateral movements"],["Innervation","Mandibular nerve (V3), branch of the trigeminal"]]],["Medulla oblongata","Brain: brainstem and cerebellum","Lower part of the brainstem, continuing with the spinal cord at the foramen magnum. It houses vital cardiovascular and respiratory centres and the nuclei of cranial nerves IX to XII; the pyramids decussate in it.",[["Cranial nerves","IX, X, XI and XII"]]],["Mentalis","Head: muscles of facial expression","Skeletal muscle. It elevates and protrudes the lower lip; it wrinkles the skin of the chin.",[["Origin","Incisive fossa of the mandible"],["Insertion","Skin of the chin"],["Action","Elevates and protrudes the lower lip; wrinkles the skin of the chin"],["Innervation","Facial nerve (VII), marginal mandibular branch"]]],["Mesocolic taenia","Digestive tract","Taenia of the colon located on the line of attachment of the mesocolon.",[]],["Midbrain","Brain: brainstem and cerebellum","Upper part of the brainstem. It contains the substantia nigra, the red nucleus and the nuclei of cranial nerves III and IV; it takes part in eye movements and motor control.",[["Cranial nerves","III (oculomotor) and IV (trochlear)"]]],["Middle cardiac vein","Heart: cardiac veins","It runs in the posterior interventricular groove and drains into the coronary sinus.",[]],["Middle frontal gyrus","Brain: cerebral cortex","Gyrus of the cerebral cortex (grey matter). It includes the frontal eye field (voluntary eye movements) and part of the dorsolateral prefrontal cortex (planning, working memory).",[["Lobe","Frontal"]]],["Middle phalanx of the fourth toe","Foot: phalanges","Bone of the toes. They are shorter than those of the hand; the big toe has only two phalanges.",[]],["Middle phalanx of the index finger","Hand: phalanges","Miniature long bone of the fingers. Located between the proximal and distal phalanges; the thumb has none.",[]],["Middle phalanx of the little finger","Hand: phalanges","Miniature long bone of the fingers. Located between the proximal and distal phalanges; the thumb has none.",[]],["Middle phalanx of the fifth toe","Foot: phalanges","Bone of the toes. They are shorter than those of the hand; the big toe has only two phalanges.",[]],["Middle phalanx of the middle finger","Hand: phalanges","Miniature long bone of the fingers. Located between the proximal and distal phalanges; the thumb has none.",[]],["Middle phalanx of the ring finger","Hand: phalanges","Miniature long bone of the fingers. Located between the proximal and distal phalanges; the thumb has none.",[]],["Middle phalanx of the second toe","Foot: phalanges","Bone of the toes. They are shorter than those of the hand; the big toe has only two phalanges.",[]],["Middle phalanx of the third toe","Foot: phalanges","Bone of the toes. They are shorter than those of the hand; the big toe has only two phalanges.",[]],["Middle temporal gyrus","Brain: cerebral cortex","Gyrus of the cerebral cortex (grey matter). It takes part in the recognition of words and meanings, and in the perception of visual motion (area MT/V5 in its posterior part).",[["Lobe","Temporal"]]],["Mitral (bicuspid) valve","Heart","Left atrioventricular valve, with two cusps. It prevents the backflow of blood from the left ventricle to the left atrium during systole.",[["Cusps","Anterior and posterior"]]],["Multifidus","Back: deep muscles (erector spinae) (transversospinal)","Deep muscle formed by short fascicles. It is a key segmental stabiliser of the lumbar spine.",[["Origin","Sacrum, iliac spines and transverse/mammillary processes from L5 to C4"],["Insertion","Spinous processes 2–4 levels above"],["Action","Stabilises the vertebral segments; extends and rotates the spine"],["Innervation","Posterior rami of the spinal nerves"]]],["Mylohyoid","Neck (suprahyoid)","Skeletal muscle. It forms the floor of the mouth; it elevates the hyoid and the tongue when swallowing.",[["Origin","Mylohyoid line of the mandible"],["Insertion","Median raphe and body of the hyoid"],["Action","Forms the floor of the mouth; elevates the hyoid and the tongue when swallowing"],["Innervation","Mylohyoid nerve (from V3)"]]],["Nasal bone","Skull","Paired, small, elongated bone that forms the bony bridge of the nose.",[]],["Nasalis","Head: muscles of facial expression","Skeletal muscle. It compresses the nostril (transverse part) or dilates it (alar part).",[["Origin","Maxilla, above the incisors and canine"],["Insertion","Aponeurosis of the nasal dorsum and alar cartilage"],["Action","Compresses the nostril (transverse part) or dilates it (alar part)"],["Innervation","Facial nerve (VII), buccal branches"]]],["Navicular (tarsal scaphoid)","Foot: tarsus","Short bone of the tarsus. The seven tarsal bones form the posterior skeleton of the foot. Located on the medial side, between the talus and the three cuneiforms; it is the keystone of the medial longitudinal arch.",[]],["Ninth rib","Thoracic cage","False rib (vertebrochondral): its cartilage joins that of the rib above, forming the costal arch.",[["No.","9th of 12 pairs"]]],["T9 vertebra","Vertebral column","Thoracic vertebra: it has costal facets on the body and on the transverse processes to articulate with the ribs, and a long spinous process pointing downward.",[]],["Adductor hallucis — oblique head","Lower limb: foot (sole, 3rd layer)","Skeletal muscle. It adducts the big toe; it supports the transverse arch.",[["Origin","Bases of metatarsals 2–4"],["Insertion","Base of the proximal phalanx of the big toe (lateral side)"],["Action","Adducts the big toe; supports the transverse arch"],["Innervation","Lateral plantar nerve (S2–S3)"]]],["Adductor pollicis — oblique head","Upper limb: hand","Skeletal muscle. It adducts the thumb.",[["Origin","Bases of metacarpals 2–3 and capitate"],["Insertion","Base of the proximal phalanx of the thumb (ulnar side)"],["Action","Adducts the thumb"],["Innervation","Ulnar nerve (deep branch)"]]],["Obliquus capitis inferior","Back: suboccipital muscles","Skeletal muscle. It turns the atlas (and the head) to the same side.",[["Origin","Spinous process of the axis"],["Insertion","Transverse process of the atlas"],["Action","Turns the atlas (and the head) to the same side"],["Innervation","Suboccipital nerve (posterior ramus of C1)"]]],["Obliquus capitis superior","Back: suboccipital muscles","Skeletal muscle. It extends and laterally tilts the head.",[["Origin","Transverse process of the atlas"],["Insertion","Occipital bone, between the superior and inferior nuchal lines"],["Action","Extends and laterally tilts the head"],["Innervation","Suboccipital nerve (posterior ramus of C1)"]]],["Obturator externus","Lower limb: hip and gluteal region (lateral rotators)","Skeletal muscle. It laterally rotates the thigh.",[["Origin","External surface of the obturator membrane"],["Insertion","Trochanteric fossa of the femur"],["Action","Laterally rotates the thigh"],["Innervation","Obturator nerve (L3–L4)"]]],["Obturator internus","Lower limb: hip and gluteal region (lateral rotators)","Skeletal muscle. It laterally rotates the thigh and stabilises the hip.",[["Origin","Internal surface of the obturator membrane and surrounding bones"],["Insertion","Medial surface of the greater trochanter"],["Action","Laterally rotates the thigh and stabilises the hip"],["Innervation","Nerve to the obturator internus (L5–S1)"]]],["Occipital bone","Skull","Unpaired bone of the posterior and lower part of the skull. It has the foramen magnum, through which the brain continues into the spinal cord, and the condyles that articulate with the atlas.",[["Type","Flat bone"],["Articulates with","Parietals, temporals, sphenoid and atlas (C1)"]]],["Occipital lobe","Brain: cerebral cortex","Posterior lobe of the cerebral hemisphere. It contains the primary visual cortex (V1, Brodmann area 17) around the calcarine sulcus and the visual association areas.",[["Function","Vision"],["Area","V1 · Brodmann 17"]]],["Occipitalis (occipital belly of occipitofrontalis)","Head: muscles of facial expression","Skeletal muscle. It pulls the scalp backward.",[["Origin","Highest nuchal line of the occipital bone and mastoid"],["Insertion","Epicranial aponeurosis"],["Action","Pulls the scalp backward"],["Innervation","Facial nerve (VII), posterior auricular branch"]]],["Omental taenia","Digestive tract","Taenia of the colon to which the greater omentum attaches on the transverse colon.",[]],["Omohyoid","Neck (infrahyoid)","Digastric muscle with an intermediate tendon attached to the clavicle by a fascial expansion. It depresses and fixes the hyoid.",[["Origin","Superior border of the scapula (inferior belly)"],["Insertion","Body of the hyoid (superior belly)"],["Action","Depresses and fixes the hyoid"],["Innervation","Ansa cervicalis (C1–C3)"]]],["Opponens digiti minimi (foot)","Lower limb: foot (sole, 3rd layer)","Skeletal muscle. It pulls the fifth metatarsal (inconstant).",[["Origin","Sheath of the fibularis longus and base of the fifth metatarsal"],["Insertion","Lateral border of the fifth metatarsal"],["Action","Pulls the fifth metatarsal (inconstant)"],["Innervation","Lateral plantar nerve (S2–S3)"]]],["Opponens digiti minimi (hand)","Upper limb: hand (hypothenar eminence)","Skeletal muscle. It brings the fifth metacarpal forward (opposition).",[["Origin","Hook of the hamate and flexor retinaculum"],["Insertion","Medial border of the fifth metacarpal"],["Action","Brings the fifth metacarpal forward (opposition)"],["Innervation","Ulnar nerve (deep branch)"]]],["Opponens pollicis","Upper limb: hand (thenar eminence)","Skeletal muscle. It opposes the thumb (brings it toward the palm to meet the other fingers).",[["Origin","Flexor retinaculum and trapezium"],["Insertion","Lateral border of the first metacarpal"],["Action","Opposes the thumb (brings it toward the palm to meet the other fingers)"],["Innervation","Median nerve (recurrent branch)"]]],["Optic chiasm","Optic pathway","X-shaped structure where the fibres from the nasal halves of both retinas cross. It lies just above the pituitary gland, so pituitary tumours can alter the visual field (bitemporal hemianopia).",[]],["Optic nerve (II)","Optic pathway","Second cranial nerve. Formed by ≈1.2 million axons of the retinal ganglion cells; it carries visual information from the eye to the optic chiasm.",[["Type","Sensory cranial nerve"]]],["Optic tract","Optic pathway","Continuation of the optic pathway from the chiasm to the lateral geniculate body. Each tract carries information from the opposite visual hemifield.",[]],["Orbicularis oris","Head: muscles of facial expression","Skeletal muscle. It closes and protrudes the lips (whistling, kissing).",[["Origin","Fibres of neighbouring muscles and maxilla and mandible near the midline"],["Insertion","Skin and mucosa of the lips"],["Action","Closes and protrudes the lips (whistling, kissing)"],["Innervation","Facial nerve (VII), buccal and mandibular branches"]]],["Orbital and rectus gyri","Brain: cerebral cortex","Gyrus of the cerebral cortex (grey matter). Inferior surface of the frontal lobe, above the roof of the orbits. Orbitofrontal cortex: decision-making, reward evaluation and control of social behaviour. The olfactory sulcus separates the gyrus rectus from the orbital gyri.",[["Lobe","Frontal"]]],["Orbicularis oculi — orbital part","Head: muscles of facial expression","Skeletal muscle. It closes the eyelids tightly (forced wink).",[["Origin","Nasal part of the frontal bone, frontal process of the maxilla and medial palpebral ligament"],["Insertion","Circular fibres that surround the orbit and return to their origin"],["Action","Closes the eyelids tightly (forced wink)"],["Innervation","Facial nerve (VII), temporal and zygomatic branches"]]],["Palatine bone","Skull","Paired L-shaped bone that forms the posterior part of the hard palate and part of the lateral wall of the nasal cavities.",[]],["Palmaris longus","Upper limb: forearm (anterior)","Inconstant muscle (absent in ≈15 % of people); its tendon is often used as a graft.",[["Origin","Medial epicondyle of the humerus"],["Insertion","Flexor retinaculum and palmar aponeurosis"],["Action","Flexes the wrist and tenses the palmar aponeurosis"],["Innervation","Median nerve (C6–C8)"]]],["Orbicularis oculi — palpebral part","Head: muscles of facial expression","Skeletal muscle. It gently closes the eyelids (blinking and sleep).",[["Origin","Medial palpebral ligament"],["Insertion","Lateral palpebral raphe"],["Action","Gently closes the eyelids (blinking and sleep)"],["Innervation","Facial nerve (VII), temporal and zygomatic branches"]]],["Pancreas","Accessory glands","Elongated retroperitoneal gland behind the stomach. Its exocrine part secretes digestive enzymes into the duodenum; its islets of Langerhans (endocrine) produce insulin and glucagon.",[["Weight","≈80–100 g"],["Parts","Head, neck, body and tail"]]],["Pancreatic duct (of Wirsung)","Accessory glands","It runs through the pancreas from tail to head and joins the common bile duct at the hepatopancreatic ampulla, which opens at the major duodenal papilla.",[]],["Papillary muscle of the left ventricle","Heart","Conical projection of the ventricular myocardium attached to the cusps by the chordae tendineae. By contracting in systole it prevents the atrioventricular valve cusps from bulging back into the atrium.",[]],["Parahippocampal gyrus","Brain: cerebral cortex","Gyrus of the cerebral cortex (grey matter). Part of the limbic system. Its anterior part (entorhinal cortex and uncus) is the main input pathway to the hippocampus; essential for memory and spatial orientation.",[["Lobe","Limbic / temporal"]]],["Parietal bone","Skull","Paired, quadrilateral bone that forms most of the roof and lateral walls of the skull. The two parietal bones meet at the sagittal suture.",[["Type","Flat bone"],["Sutures","Coronal, sagittal, lambdoid and squamous"]]],["Patella","Lower limb","The largest sesamoid bone in the body, embedded in the quadriceps tendon. It protects the knee and increases the lever arm of the quadriceps in extension.",[["Type","Sesamoid bone"]]],["Pectineus","Lower limb: thigh (medial)","Skeletal muscle. It adducts and flexes the thigh.",[["Origin","Pectineal line of the pubis"],["Insertion","Pectineal line of the femur"],["Action","Adducts and flexes the thigh"],["Innervation","Femoral nerve (sometimes also obturator)"]]],["Pectoralis minor","Thorax","Skeletal muscle. It depresses and protracts the scapula; it elevates the ribs if the scapula is fixed.",[["Origin","Ribs 3–5"],["Insertion","Coracoid process of the scapula"],["Action","Depresses and protracts the scapula; elevates the ribs if the scapula is fixed"],["Innervation","Medial pectoral nerve (C8–T1)"]]],["Cerebral peduncle","Brain: brainstem and cerebellum","Anterior column of the midbrain formed by the base of the peduncle, which contains the descending corticospinal and corticonuclear fibres.",[]],["Pineal gland (epiphysis)","Endocrine glands","Small pine cone–shaped gland of the epithalamus, located behind the third ventricle. It secretes melatonin in darkness and regulates circadian rhythms.",[["Hormone","Melatonin"]]],["Piriformis","Lower limb: hip and gluteal region (lateral rotators)","Key landmark of the gluteal region: the sciatic nerve usually leaves the pelvis below it.",[["Origin","Anterior surface of the sacrum"],["Insertion","Superior border of the greater trochanter"],["Action","Laterally rotates the extended thigh; abducts it in flexion"],["Innervation","Nerve to the piriformis (S1–S2)"]]],["Pisiform","Hand: carpus","Short bone of the carpus. The eight carpal bones are arranged in two rows and form the skeleton of the wrist. Proximal row; it is a sesamoid bone within the tendon of the flexor carpi ulnaris.",[]],["Pituitary gland (hypophysis)","Endocrine glands","Gland of ≈0.5 g housed in the sella turcica of the sphenoid and connected to the hypothalamus by the pituitary stalk. It regulates other glands: the adenohypophysis secretes GH, TSH, ACTH, FSH, LH and prolactin; the neurohypophysis releases oxytocin and ADH.",[["Weight","≈0.5 g"],["Lobes","Adenohypophysis and neurohypophysis"]]],["Plantaris","Lower limb: leg (posterior)","Small muscle with a very long, thin tendon; inconstant.",[["Origin","Lateral supracondylar line of the femur"],["Insertion","Calcaneal tuberosity (medial to the calcaneal tendon)"],["Action","Weak plantar flexion and knee flexion"],["Innervation","Tibial nerve (S1–S2)"]]],["Platysma","Head: muscles of facial expression","Skeletal muscle. It tenses the skin of the neck and depresses the lower lip and the mandible.",[["Origin","Fascia of the upper chest (pectoralis major and deltoid)"],["Insertion","Inferior border of the mandible and skin of the lower face"],["Action","Tenses the skin of the neck and depresses the lower lip and the mandible"],["Innervation","Facial nerve (VII), cervical branch"]]],["Pons","Brain: brainstem and cerebellum","Middle part of the brainstem. It connects the cortex with the cerebellum and contains respiratory centres and the nuclei of cranial nerves V, VI, VII and VIII.",[["Cranial nerves","V, VI, VII and VIII"]]],["Popliteus","Lower limb: leg (posterior)","Skeletal muscle. It \"unlocks\" the extended knee by laterally rotating the femur.",[["Origin","Lateral condyle of the femur and lateral meniscus"],["Insertion","Posterior surface of the tibia, above the soleal line"],["Action","\"Unlocks\" the extended knee by laterally rotating the femur"],["Innervation","Tibial nerve (S1–S2)"]]],["Postcentral gyrus","Brain: cerebral cortex","Gyrus of the cerebral cortex (grey matter). Primary somatosensory cortex (areas 3, 1 and 2): it receives touch, pain, temperature and proprioception from the opposite side of the body (sensory homunculus).",[["Lobe","Parietal"],["Area","S1 · Brodmann 3-1-2"]]],["Digastric — posterior belly","Neck (suprahyoid)","Skeletal muscle. It elevates and retracts the hyoid during swallowing.",[["Origin","Mastoid notch of the temporal bone"],["Insertion","Intermediate tendon, attached to the hyoid"],["Action","Elevates and retracts the hyoid during swallowing"],["Innervation","Facial nerve (VII)"]]],["Posterior commissure","Brain: white matter","Bundle of fibres that crosses the midline above the cerebral aqueduct; it takes part in the consensual pupillary light reflex.",[]],["Superior temporal gyrus (posterior part)","Brain: cerebral cortex","Gyrus of the cerebral cortex (grey matter). In the dominant hemisphere it contains Wernicke's area, essential for language comprehension.",[["Lobe","Temporal"],["Area","Wernicke · Brodmann 22"]]],["Precentral gyrus","Brain: cerebral cortex","Gyrus of the cerebral cortex (grey matter). Primary motor cortex (Brodmann area 4): it originates voluntary motor commands for the opposite side of the body, with a somatotopic representation (motor homunculus).",[["Lobe","Frontal"],["Area","M1 · Brodmann 4"]]],["Procerus","Head: muscles of facial expression","Skeletal muscle. It lowers the medial end of the eyebrows and produces transverse wrinkles at the root of the nose.",[["Origin","Fascia of the nasal bone and lateral nasal cartilage"],["Insertion","Skin between the eyebrows"],["Action","Lowers the medial end of the eyebrows and produces transverse wrinkles at the root of the nose"],["Innervation","Facial nerve (VII)"]]],["Pronator quadratus","Upper limb: forearm (anterior)","Skeletal muscle. Main pronator of the forearm.",[["Origin","Distal quarter of the anterior surface of the ulna"],["Insertion","Distal quarter of the anterior surface of the radius"],["Action","Main pronator of the forearm"],["Innervation","Anterior interosseous nerve (of the median)"]]],["Prostate","Male reproductive system","Walnut-sized gland below the bladder, crossed by the urethra. It produces ≈20–30 % of the semen. Its growth with age (benign hyperplasia) can make urination difficult.",[["Weight","≈20 g"]]],["Proximal phalanx of the big toe (hallux)","Foot: phalanges","Bone of the toes. They are shorter than those of the hand; the big toe has only two phalanges.",[]],["Proximal phalanx of the fourth toe","Foot: phalanges","Bone of the toes. They are shorter than those of the hand; the big toe has only two phalanges.",[]],["Proximal phalanx of the index finger","Hand: phalanges","Miniature long bone of the fingers. It articulates with the head of the metacarpal (metacarpophalangeal joint).",[]],["Proximal phalanx of the little finger","Hand: phalanges","Miniature long bone of the fingers. It articulates with the head of the metacarpal (metacarpophalangeal joint).",[]],["Proximal phalanx of the fifth toe","Foot: phalanges","Bone of the toes. They are shorter than those of the hand; the big toe has only two phalanges.",[]],["Proximal phalanx of the middle finger","Hand: phalanges","Miniature long bone of the fingers. It articulates with the head of the metacarpal (metacarpophalangeal joint).",[]],["Proximal phalanx of the ring finger","Hand: phalanges","Miniature long bone of the fingers. It articulates with the head of the metacarpal (metacarpophalangeal joint).",[]],["Proximal phalanx of the second toe","Foot: phalanges","Bone of the toes. They are shorter than those of the hand; the big toe has only two phalanges.",[]],["Proximal phalanx of the third toe","Foot: phalanges","Bone of the toes. They are shorter than those of the hand; the big toe has only two phalanges.",[]],["Proximal phalanx of the thumb","Hand: phalanges","Miniature long bone of the fingers. It articulates with the head of the metacarpal (metacarpophalangeal joint).",[]],["Psoas major","Lower limb: hip and gluteal region","Long muscle of the posterior abdominal wall; with the iliacus it forms the iliopsoas, the most powerful hip flexor.",[["Origin","Bodies and transverse processes of T12–L5 and intervertebral discs"],["Insertion","Lesser trochanter of the femur (with the iliacus)"],["Action","Flexes the thigh at the hip; flexes the trunk"],["Innervation","Anterior rami of L1–L3"]]],["Pubococcygeus","Pelvis: pelvic floor (levator ani)","Part of the levator ani, the main component of the pelvic diaphragm.",[["Origin","Body of the pubis and tendinous arch of the levator ani"],["Insertion","Coccyx and anococcygeal ligament"],["Action","Supports the pelvic viscera and resists increases in abdominal pressure"],["Innervation","Nerve to the levator ani (S4) and branches of the pudendal nerve"]]],["Puborectalis","Pelvis: pelvic floor (levator ani)","Skeletal muscle. It maintains the anorectal angle; essential for faecal continence.",[["Origin","Body of the pubis"],["Insertion","Forms a U-shaped sling around the anorectal junction"],["Action","Maintains the anorectal angle; essential for faecal continence"],["Innervation","Nerve to the levator ani (S4) and pudendal nerve"]]],["Pulmonary arteries (pulmonary trunk)","Major arteries","They carry oxygen-poor blood from the right ventricle to the lungs. The pulmonary trunk divides into the right and left pulmonary arteries below the aortic arch. They are the only arteries in the adult that carry deoxygenated blood.",[]],["Pulmonary valve","Heart","Semilunar valve with three cusps located between the right ventricle and the pulmonary trunk. It prevents backflow into the ventricle during diastole.",[]],["Pulmonary veins","Major veins","Normally four (two per lung). They carry oxygenated blood from the lungs to the left atrium. They are the only veins in the adult that carry oxygenated blood.",[]],["Putamen","Brain: deep nuclei","Lateral part of the lentiform nucleus. With the caudate it forms the striatum, which receives information from the cortex and regulates movement. Affected in Parkinson's disease by the loss of dopamine.",[["Group","Basal ganglia"]]],["Pyramidalis","Abdomen","Small triangular, inconstant muscle (absent in ≈20 % of people), located in front of the rectus abdominis.",[["Origin","Body of the pubis"],["Insertion","Linea alba"],["Action","Tenses the linea alba"],["Innervation","Subcostal nerve (T12)"]]],["Quadratus femoris","Lower limb: hip and gluteal region (lateral rotators)","Skeletal muscle. It laterally rotates the thigh.",[["Origin","Ischial tuberosity"],["Insertion","Intertrochanteric crest of the femur"],["Action","Laterally rotates the thigh"],["Innervation","Nerve to the quadratus femoris (L5–S1)"]]],["Quadratus lumborum","Abdomen (posterior wall)","Skeletal muscle. It laterally tilts the trunk and fixes the twelfth rib during inspiration.",[["Origin","Iliolumbar ligament and iliac crest"],["Insertion","Twelfth rib and transverse processes of L1–L4"],["Action","Laterally tilts the trunk and fixes the twelfth rib during inspiration"],["Innervation","Anterior rami of T12–L4"]]],["Flexor digitorum superficialis — radial head","Upper limb: forearm (anterior)","Skeletal muscle. It flexes the proximal interphalangeal joints.",[["Origin","Anterior border of the radius"],["Insertion","Middle phalanges of toes 2–5"],["Action","Flexes the proximal interphalangeal joints"],["Innervation","Median nerve (C6–C8)"]]],["Radius","Upper limb","Lateral bone of the forearm (thumb side). It rotates around the ulna in pronation and supination. Its distal end forms most of the wrist joint.",[["Type","Long bone"]]],["Rectum","Digestive tract","Final part of the large intestine (≈12–15 cm), between the sigmoid colon (S3) and the anal canal. It temporarily stores faeces.",[["Length","≈12–15 cm"]]],["Rectus abdominis","Abdomen","Long, flat muscle enclosed in the rectus sheath; its tendinous intersections give the \"six-pack\" look. It flexes the trunk.",[["Origin","Pubic crest and pubic symphysis"],["Insertion","Costal cartilages 5–7 and xiphoid process"],["Action","Flexes the trunk and compresses the abdominal viscera"],["Innervation","Thoracoabdominal nerves T7–T11 and subcostal nerve (T12)"]]],["Rectus capitis anterior","Neck (prevertebral)","Skeletal muscle. It flexes the head at the atlanto-occipital joint.",[["Origin","Lateral mass of the atlas"],["Insertion","Basilar part of the occipital bone"],["Action","Flexes the head at the atlanto-occipital joint"],["Innervation","Anterior rami of C1–C2"]]],["Rectus capitis lateralis","Neck (prevertebral)","Skeletal muscle. It laterally tilts the head.",[["Origin","Transverse process of the atlas"],["Insertion","Jugular process of the occipital bone"],["Action","Laterally tilts the head"],["Innervation","Anterior rami of C1–C2"]]],["Rectus capitis posterior major","Back: suboccipital muscles","Skeletal muscle. It extends the head and turns it to the same side.",[["Origin","Spinous process of the axis"],["Insertion","Lateral part of the inferior nuchal line"],["Action","Extends the head and turns it to the same side"],["Innervation","Suboccipital nerve (posterior ramus of C1)"]]],["Rectus capitis posterior minor","Back: suboccipital muscles","Skeletal muscle. It extends the head.",[["Origin","Posterior tubercle of the atlas"],["Insertion","Medial part of the inferior nuchal line"],["Action","Extends the head"],["Innervation","Suboccipital nerve (posterior ramus of C1)"]]],["Rectus femoris","Lower limb: thigh (anterior) (quadriceps)","The only head of the quadriceps that crosses the hip. It extends the knee and flexes the hip.",[["Origin","Anterior inferior iliac spine and superior border of the acetabulum"],["Insertion","Tibial tuberosity via the patellar tendon"],["Action","Extends the knee and flexes the hip"],["Innervation","Femoral nerve (L2–L4)"]]],["Renal artery","Major arteries (abdominal)","It arises from the aorta at L1–L2. The kidneys receive ≈20 % of the cardiac output. The right one is longer and passes behind the inferior vena cava.",[]],["Renal vein","Major veins","It drains the kidney into the inferior vena cava. The left one is longer and crosses in front of the aorta, below the superior mesenteric artery.",[]],["Rhomboid major","Back: superficial muscles","Skeletal muscle. It retracts and elevates the scapula; it fixes it to the chest wall.",[["Origin","Spinous processes of T2–T5"],["Insertion","Medial border of the scapula, below the spine"],["Action","Retracts and elevates the scapula; fixes it to the chest wall"],["Innervation","Dorsal scapular nerve (C4–C5)"]]],["Rhomboid minor","Back: superficial muscles","Skeletal muscle. It retracts and elevates the scapula.",[["Origin","Nuchal ligament and spinous processes of C7–T1"],["Insertion","Medial border of the scapula, at the level of the spine"],["Action","Retracts and elevates the scapula"],["Innervation","Dorsal scapular nerve (C4–C5)"]]],["Risorius","Head: muscles of facial expression","Skeletal muscle. It pulls the angle of the mouth laterally.",[["Origin","Parotid and masseteric fascia"],["Insertion","Angle of the mouth"],["Action","Pulls the angle of the mouth laterally"],["Innervation","Facial nerve (VII), buccal branches"]]],["Sacrum","Vertebral column","Triangular bone formed by the fusion of the five sacral vertebrae. It wedges between the two hip bones at the sacroiliac joints and transmits the weight of the trunk to the pelvis.",[["Formed by","Fusion of S1–S5"],["Articulates with","L5, hip bones and coccyx"]]],["Sartorius","Lower limb: thigh (anterior)","The longest muscle in the body. It crosses the thigh diagonally and acts on the hip and knee.",[["Origin","Anterior superior iliac spine"],["Insertion","Medial surface of the upper tibia (pes anserinus)"],["Action","Flexes, abducts and laterally rotates the hip; flexes the knee (tailor's position)"],["Innervation","Femoral nerve (L2–L4)"]]],["Scalenus anterior","Neck (scalenes)","Deep muscle of the neck. The subclavian artery passes behind it and the subclavian vein in front of it.",[["Origin","Anterior tubercles of the transverse processes of C3–C6"],["Insertion","Scalene tubercle of the first rib"],["Action","Elevates the first rib (forced inspiration); tilts the neck"],["Innervation","Anterior rami of C4–C6"]]],["Scalenus medius","Neck (scalenes)","Skeletal muscle. It elevates the first rib; it tilts the neck.",[["Origin","Posterior tubercles of the transverse processes of C2–C7"],["Insertion","Superior surface of the first rib"],["Action","Elevates the first rib; tilts the neck"],["Innervation","Anterior rami of C3–C8"]]],["Scalenus posterior","Neck (scalenes)","Skeletal muscle. It elevates the second rib; it tilts the neck.",[["Origin","Posterior tubercles of the transverse processes of C4–C6"],["Insertion","External surface of the second rib"],["Action","Elevates the second rib; tilts the neck"],["Innervation","Anterior rami of C6–C8"]]],["Scaphoid","Hand: carpus","Short bone of the carpus. The eight carpal bones are arranged in two rows and form the skeleton of the wrist. The scaphoid (proximal row) is the one fractured most frequently; its retrograde blood supply favours necrosis after fracture.",[]],["Scapula (shoulder blade)","Upper limb","Flat, triangular bone of the posterior part of the thorax. Its glenoid cavity articulates with the head of the humerus to form the shoulder; the spine ends in the acromion.",[["Landmarks","Spine, acromion, coracoid process, glenoid cavity"]]],["Second costal cartilage","Thoracic cage","Hyaline cartilage that joins the anterior end of the rib to the sternum. Its elasticity allows the thoracic cage to expand during breathing.",[]],["L2 vertebra","Vertebral column","Lumbar vertebra: the largest, with a kidney-shaped, robust body adapted to bear the weight of the trunk. Its spinous processes are short and horizontal.",[]],["Second lumbrical of the foot","Lower limb: foot (sole, 2nd layer)","Skeletal muscle. It flexes the metatarsophalangeal joint and extends the interphalangeal joints.",[["Origin","Tendons of the flexor digitorum longus"],["Insertion","Extensor expansion of the third toe"],["Action","Flexes the metatarsophalangeal joint and extends the interphalangeal joints"],["Innervation","Lateral plantar nerve (S2–S3)"]]],["Second metacarpal","Hand: metacarpus","Long bone of the palm of the hand. Its base articulates with the carpus and its head with the proximal phalanx (knuckle). Metacarpal of the index finger; the longest.",[]],["Second metatarsal","Foot: metatarsus","Long bone of the forefoot. Its base articulates with the tarsus and its head with the proximal phalanx; the metatarsal heads rest on the ground during walking. It is the longest; frequent in stress fractures.",[]],["Second plantar interosseous","Lower limb: foot (sole, 4th layer)","Skeletal muscle. It adducts the toe toward the axis of the second toe.",[["Origin","Medial surface of the fourth metatarsal"],["Insertion","Base of the proximal phalanx of the fourth toe (medial side)"],["Action","Adducts the toe toward the axis of the second toe"],["Innervation","Lateral plantar nerve (S2–S3)"]]],["Second rib","Thoracic cage","True rib (vertebrosternal): it joins the sternum directly through its own costal cartilage.",[["No.","2nd of 12 pairs"]]],["T2 vertebra","Vertebral column","Thoracic vertebra: it has costal facets on the body and on the transverse processes to articulate with the ribs, and a long spinous process pointing downward.",[]],["Semimembranosus","Lower limb: thigh (posterior, hamstrings)","Skeletal muscle. It flexes the knee, extends the hip and medially rotates the leg.",[["Origin","Ischial tuberosity"],["Insertion","Medial condyle of the tibia (posterior surface)"],["Action","Flexes the knee, extends the hip and medially rotates the leg"],["Innervation","Sciatic nerve, tibial part (L5–S2)"]]],["Seminal vesicle","Male reproductive system","Tubular gland located behind the bladder. It provides ≈60–70 % of the semen volume, a fructose-rich fluid that nourishes the sperm.",[]],["Semispinalis capitis","Back: deep muscles (erector spinae) (transversospinal)","Skeletal muscle. Main extensor of the head.",[["Origin","Transverse processes of C7–T6 and articular processes of C4–C6"],["Insertion","Occipital bone, between the nuchal lines"],["Action","Main extensor of the head"],["Innervation","Posterior rami of the spinal nerves"]]],["Semispinalis cervicis","Back: deep muscles (erector spinae) (transversospinal)","Skeletal muscle. It extends the neck and turns it to the opposite side.",[["Origin","Transverse processes of T1–T6"],["Insertion","Spinous processes of C2–C5"],["Action","Extends the neck and turns it to the opposite side"],["Innervation","Posterior rami of the spinal nerves"]]],["Semispinalis thoracis","Back: deep muscles (erector spinae) (transversospinal)","Skeletal muscle. It extends the spine and turns it to the opposite side.",[["Origin","Transverse processes of T6–T10"],["Insertion","Spinous processes of C6–T4"],["Action","Extends the spine and turns it to the opposite side"],["Innervation","Posterior rami of the spinal nerves"]]],["Semitendinosus","Lower limb: thigh (posterior, hamstrings)","Skeletal muscle. It flexes the knee, extends the hip and medially rotates the leg.",[["Origin","Ischial tuberosity"],["Insertion","Medial surface of the upper tibia (pes anserinus)"],["Action","Flexes the knee, extends the hip and medially rotates the leg"],["Innervation","Sciatic nerve, tibial part (L5–S2)"]]],["Septal papillary muscle of the right ventricle","Heart","Conical projection of the ventricular myocardium attached to the cusps by the chordae tendineae. By contracting in systole it prevents the atrioventricular valve cusps from bulging back into the atrium.",[]],["Septum pellucidum","Brain: white matter","Thin double sheet that separates the anterior horns of the lateral ventricles, between the corpus callosum and the fornix.",[]],["Serratus anterior","Thorax","Its paralysis produces a \"winged scapula\". It protracts and rotates the scapula.",[["Origin","External surfaces of ribs 1–8 (or 9)"],["Insertion","Medial border of the scapula (costal surface)"],["Action","Protracts the scapula and rotates it upward; keeps it pressed against the thorax"],["Innervation","Long thoracic nerve (C5–C7)"]]],["Serratus posterior inferior","Back: superficial muscles (intermediate)","Skeletal muscle. It lowers the lower ribs.",[["Origin","Spinous processes of T11–L2"],["Insertion","Ribs 9–12"],["Action","Lowers the lower ribs"],["Innervation","Intercostal nerves T9–T11 and subcostal nerve"]]],["Serratus posterior superior","Back: superficial muscles (intermediate)","Skeletal muscle. It elevates the ribs (an inspiratory function is attributed to it).",[["Origin","Nuchal ligament and spinous processes of C7–T3"],["Insertion","Ribs 2–5"],["Action","Elevates the ribs (an inspiratory function is attributed to it)"],["Innervation","Intercostal nerves T2–T5"]]],["Sesamoid bones of the foot","Foot: metatarsus","Small bones embedded in the tendons of the flexor hallucis brevis, under the head of the first metatarsal. They protect the tendon and improve its leverage.",[]],["Anterior cardiac veins","Heart: cardiac veins","Small veins of the anterior surface of the right ventricle that open directly into the right atrium.",[]],["Anterior intertransversarii of the neck","Back: deep muscles (erector spinae) (segmental)","Skeletal muscle. Lateral tilt and stabilisation of the neck.",[["Origin","Anterior tubercle of a cervical transverse process"],["Insertion","Anterior tubercle of the transverse process above"],["Action","Lateral tilt and stabilisation of the neck"],["Innervation","Anterior rami of the cervical nerves"]]],["Dorsal interossei of the foot","Lower limb: foot (sole, 4th layer)","Skeletal muscle. They abduct the toes away from the axis of the second toe.",[["Origin","Adjacent surfaces of the metatarsals (double heads)"],["Insertion","Proximal phalanges of toes 2–4"],["Action","Abduct the toes away from the axis of the second toe"],["Innervation","Lateral plantar nerve (S2–S3)"]]],["Dorsal interossei of the hand","Upper limb: hand","Skeletal muscle. They abduct the fingers away from the axis of the middle finger (DAB).",[["Origin","Adjacent surfaces of the five metacarpals (double heads)"],["Insertion","Proximal phalanges and extensor expansions of fingers 2–4"],["Action","Abduct the fingers away from the axis of the middle finger (DAB)"],["Innervation","Ulnar nerve (deep branch)"]]],["Eyebrows","Skin appendages","Thick hairs located on the supraorbital margin. They divert sweat and water away from the eyes and take part in facial expression.",[]],["Scalp hair","Skin appendages","Set of terminal hairs of the scalp. Each hair arises from a hair follicle in the dermis; it is made of hard keratin and grows about 1 cm per month.",[["Tissue","Keratin (epidermal appendage)"],["Function","Protection against solar radiation and thermal insulation"]]],["Interspinales cervicis","Back: deep muscles (erector spinae) (segmental)","Skeletal muscle. They extend the neck and stabilise it.",[["Origin","Spinous process of a cervical vertebra"],["Insertion","Spinous process of the vertebra above"],["Action","Extend the neck and stabilise it"],["Innervation","Posterior rami of the spinal nerves"]]],["Interspinales lumborum","Back: deep muscles (erector spinae) (segmental)","Skeletal muscle. They extend and stabilise the lumbar spine.",[["Origin","Spinous process of a lumbar vertebra"],["Insertion","Spinous process of the vertebra above"],["Action","Extend and stabilise the lumbar spine"],["Innervation","Posterior rami of the spinal nerves"]]],["Interspinales thoracis","Back: deep muscles (erector spinae) (segmental)","Skeletal muscle. They extend and stabilise the spine.",[["Origin","Thoracic spinous processes (inconstant, at the ends of the region)"],["Insertion","Spinous process of the vertebra above"],["Action","Extend and stabilise the spine"],["Innervation","Posterior rami of the spinal nerves"]]],["Lateral intertransversarii lumborum","Back: deep muscles (erector spinae) (segmental)","Skeletal muscle. Lateral tilt of the lumbar spine.",[["Origin","Lumbar transverse (costal) process"],["Insertion","Transverse process above"],["Action","Lateral tilt of the lumbar spine"],["Innervation","Anterior rami of the lumbar nerves"]]],["Levatores costarum breves","Back: deep muscles (erector spinae) (segmental)","Skeletal muscle. They elevate the ribs; they tilt the spine.",[["Origin","Transverse processes of C7–T11"],["Insertion","Rib immediately below, between tubercle and angle"],["Action","Elevate the ribs; tilt the spine"],["Innervation","Posterior rami of the spinal nerves C8–T11"]]],["Levatores costarum longi","Back: deep muscles (erector spinae) (segmental)","Skeletal muscle. They elevate the ribs; they tilt the spine.",[["Origin","Transverse processes of T7–T10"],["Insertion","Rib two levels below"],["Action","Elevate the ribs; tilt the spine"],["Innervation","Posterior rami of the spinal nerves C8–T11"]]],["Lumbricals of the hand","Upper limb: hand","Skeletal muscle. They flex the metacarpophalangeal joints and extend the interphalangeal joints.",[["Origin","Tendons of the flexor digitorum profundus"],["Insertion","Extensor expansions of fingers 2–5 (radial side)"],["Action","Flex the metacarpophalangeal joints and extend the interphalangeal joints"],["Innervation","Median nerve (1st–2nd) and ulnar nerve (3rd–4th)"]]],["Medial intertransversarii lumborum","Back: deep muscles (erector spinae) (segmental)","Skeletal muscle. Lateral tilt and lumbar stabilisation.",[["Origin","Lumbar accessory process"],["Insertion","Mammillary process of the vertebra above"],["Action","Lateral tilt and lumbar stabilisation"],["Innervation","Posterior rami of the spinal nerves"]]],["Nasal cartilages","Airways","Hyaline cartilages that form the skeleton of the movable part of the nose: greater alar, lateral and septal cartilages.",[]],["Palmar interossei","Upper limb: hand","Skeletal muscle. They adduct the fingers toward the axis of the middle finger (PAD).",[["Origin","Palmar surfaces of metacarpals 2, 4 and 5"],["Insertion","Extensor expansions and proximal phalanges of those fingers"],["Action","Adduct the fingers toward the axis of the middle finger (PAD)"],["Innervation","Ulnar nerve (deep branch)"]]],["Posterior intertransversarii of the neck","Back: deep muscles (erector spinae) (segmental)","Skeletal muscle. Lateral tilt and stabilisation of the neck.",[["Origin","Posterior tubercle of a cervical transverse process"],["Insertion","Posterior tubercle of the transverse process above"],["Action","Lateral tilt and stabilisation of the neck"],["Innervation","Posterior rami of the spinal nerves"]]],["Pubic hair","Skin appendages","Terminal hair of the pubic region, which appears at puberty under the action of androgens. It is a secondary sexual characteristic.",[]],["C7 vertebra","Vertebral column","Vertebra prominens: its long, non-bifid spinous process is easily palpable at the base of the neck and serves as a clinical landmark.",[]],["Seventh costal cartilage","Thoracic cage","Hyaline cartilage that joins the anterior end of the rib to the sternum. Its elasticity allows the thoracic cage to expand during breathing.",[]],["Seventh rib","Thoracic cage","True rib (vertebrosternal): it joins the sternum directly through its own costal cartilage.",[["No.","7th of 12 pairs"]]],["T7 vertebra","Vertebral column","Thoracic vertebra: it has costal facets on the body and on the transverse processes to articulate with the ribs, and a long spinous process pointing downward.",[]],["Biceps brachii — short head","Upper limb: arm","Skeletal muscle. Powerful supinator of the forearm and flexor of the elbow.",[["Origin","Coracoid process of the scapula"],["Insertion","Radial tuberosity and bicipital aponeurosis"],["Action","Powerful supinator of the forearm and flexor of the elbow"],["Innervation","Musculocutaneous nerve (C5–C6)"]]],["Biceps femoris — short head","Lower limb: thigh (posterior, hamstrings)","Skeletal muscle. It flexes the knee and laterally rotates the leg.",[["Origin","Lateral lip of the linea aspera"],["Insertion","Head of the fibula"],["Action","Flexes the knee and laterally rotates the leg"],["Innervation","Sciatic nerve, common fibular part (L5–S2)"]]],["C6 vertebra","Vertebral column","Typical cervical vertebra: small body, transverse foramina through which the vertebral artery ascends (C1–C6) and a short spinous process, bifid in C3–C6.",[]],["Sixth costal cartilage","Thoracic cage","Hyaline cartilage that joins the anterior end of the rib to the sternum. Its elasticity allows the thoracic cage to expand during breathing.",[]],["Sixth rib","Thoracic cage","True rib (vertebrosternal): it joins the sternum directly through its own costal cartilage.",[["No.","6th of 12 pairs"]]],["T6 vertebra","Vertebral column","Thoracic vertebra: it has costal facets on the body and on the transverse processes to articulate with the ribs, and a long spinous process pointing downward.",[]],["Skin","Skin","Organ that covers the entire body surface (≈1.8 m² and ≈4 kg in adults). It consists of the epidermis (keratinised stratified squamous epithelium), the dermis (connective tissue with vessels, nerves, hair follicles and glands) and rests on the hypodermis or subcutaneous tissue.",[["Functions","Protective barrier, thermoregulation, sensation, vitamin D synthesis"],["Layers","Epidermis · dermis · (hypodermis)"]]],["Soleus","Lower limb: leg (posterior) (triceps surae)","Broad, flat muscle under the gastrocnemius. Its contraction drives venous blood toward the heart (\"muscle pump\").",[["Origin","Head and posterior surface of the fibula and soleal line of the tibia"],["Insertion","Calcaneal tuberosity via the calcaneal tendon"],["Action","Plantar flexion of the foot; key for standing upright"],["Innervation","Tibial nerve (S1–S2)"]]],["Sphenoid bone","Skull","Unpaired butterfly-shaped bone located in the centre of the base of the skull. Its sella turcica houses the pituitary gland and it articulates with all the other bones of the neurocranium.",[["Parts","Body, greater wings, lesser wings and pterygoid processes"]]],["Deltoid — spinal (posterior) part","Upper limb: shoulder","Skeletal muscle. It extends and laterally rotates the arm.",[["Origin","Spine of the scapula"],["Insertion","Deltoid tuberosity of the humerus"],["Action","Extends and laterally rotates the arm"],["Innervation","Axillary nerve (C5–C6)"]]],["Spinalis cervicis","Back: deep muscles (erector spinae)","Skeletal muscle. It extends the neck.",[["Origin","Nuchal ligament and spinous processes of C7–T2"],["Insertion","Spinous process of the axis"],["Action","Extends the neck"],["Innervation","Posterior rami of the spinal nerves"]]],["Spinalis thoracis","Back: deep muscles (erector spinae)","Skeletal muscle. It extends the thoracic spine.",[["Origin","Spinous processes of T11–L2"],["Insertion","Spinous processes of T1–T8"],["Action","Extends the thoracic spine"],["Innervation","Posterior rami of the spinal nerves"]]],["Spleen","Lymphoid organs","Lymphoid organ located in the left hypochondrium, under ribs 9–11. Its red pulp filters the blood and removes aged red blood cells; its white pulp generates immune responses against blood-borne pathogens.",[["Weight","≈150 g"],["Location","Left hypochondrium"]]],["Splenic artery","Major arteries (abdominal)","The thickest branch of the celiac trunk; it runs tortuously along the upper border of the pancreas to the spleen.",[]],["Splenic vein","Major veins (portal system)","It drains the spleen and part of the pancreas and stomach; after receiving the inferior mesenteric vein it joins the superior mesenteric vein behind the neck of the pancreas to form the portal vein.",[]],["Splenius capitis","Back: deep muscles (erector spinae)","Skeletal muscle. It extends the head; unilaterally it turns it to the same side.",[["Origin","Nuchal ligament and spinous processes of C7–T3"],["Insertion","Mastoid process and lateral third of the superior nuchal line"],["Action","Extends the head; unilaterally it turns it to the same side"],["Innervation","Posterior rami of the middle cervical spinal nerves"]]],["Splenius cervicis","Back: deep muscles (erector spinae)","Skeletal muscle. It extends the neck and turns it to the same side.",[["Origin","Spinous processes of T3–T6"],["Insertion","Transverse processes of C1–C3"],["Action","Extends the neck and turns it to the same side"],["Innervation","Posterior rami of the lower cervical spinal nerves"]]],["Sternocleidomastoid","Neck","Skeletal muscle. Unilateral: it tilts the head to the same side and turns it to the opposite side. Bilateral: it flexes the neck; accessory inspiratory muscle.",[["Origin","Manubrium of the sternum (sternal head) and medial third of the clavicle (clavicular head)"],["Insertion","Mastoid process of the temporal bone and superior nuchal line"],["Action","Unilateral: tilts the head to the same side and turns it to the opposite side. Bilateral: flexes the neck; accessory inspiratory muscle"],["Innervation","Accessory nerve (XI) and branches of C2–C3"]]],["Pectoralis major — sternocostal part","Thorax","Skeletal muscle. It adducts and medially rotates the arm; it extends it from flexion.",[["Origin","Anterior surface of the sternum and costal cartilages 1–6"],["Insertion","Crest of the greater tubercle of the humerus"],["Action","Adducts and medially rotates the arm; extends it from flexion"],["Innervation","Lateral and medial pectoral nerves (C5–T1)"]]],["Sternohyoid","Neck (infrahyoid)","Skeletal muscle. It lowers the hyoid after swallowing.",[["Origin","Manubrium of the sternum and medial end of the clavicle"],["Insertion","Body of the hyoid bone"],["Action","Lowers the hyoid after swallowing"],["Innervation","Ansa cervicalis (C1–C3)"]]],["Sternothyroid","Neck (infrahyoid)","Skeletal muscle. It lowers the larynx.",[["Origin","Posterior surface of the manubrium of the sternum"],["Insertion","Oblique line of the thyroid cartilage"],["Action","Lowers the larynx"],["Innervation","Ansa cervicalis (C1–C3)"]]],["Stomach","Digestive tract","J-shaped dilation of the digestive tract located in the epigastrium and left hypochondrium. It stores food and partially digests it with hydrochloric acid and pepsin, turning it into chyme.",[["Capacity","≈1–1.5 L (up to 2–3 L)"],["Parts","Cardia, fundus, body, antrum and pylorus"]]],["Stria medullaris thalami","Brain: white matter","Bundle of fibres on the medial surface of the thalamus that carries information from the septal area to the habenular nuclei.",[]],["Stria terminalis","Brain: white matter","Bundle of fibres that runs alongside the caudate nucleus and connects the amygdala with the hypothalamus and the septal area.",[]],["Stylohyoid","Neck (suprahyoid)","Skeletal muscle. It elevates and retracts the hyoid.",[["Origin","Styloid process of the temporal bone"],["Insertion","Body of the hyoid"],["Action","Elevates and retracts the hyoid"],["Innervation","Facial nerve (VII)"]]],["Subclavian artery","Major arteries","Main artery of the upper limb. It passes between the scalenus anterior and medius over the first rib and continues as the axillary artery. It gives off the vertebral artery, which supplies the posterior brain.",[]],["Subclavian vein","Major veins","Continuation of the axillary vein. It passes in front of the scalenus anterior, over the first rib, and joins the internal jugular vein. It is a common route for central venous access.",[]],["Subclavius","Thorax","Skeletal muscle. It fixes and lowers the clavicle.",[["Origin","Junction of the first rib with its cartilage"],["Insertion","Inferior surface of the middle third of the clavicle"],["Action","Fixes and lowers the clavicle"],["Innervation","Nerve to the subclavius (C5–C6)"]]],["Subscapularis","Upper limb: shoulder (rotator cuff)","Skeletal muscle. It medially rotates the arm and stabilises the shoulder.",[["Origin","Subscapular fossa (anterior surface of the scapula)"],["Insertion","Lesser tubercle of the humerus"],["Action","Medially rotates the arm and stabilises the shoulder"],["Innervation","Upper and lower subscapular nerves (C5–C6)"]]],["Flexor pollicis brevis — superficial head","Upper limb: hand (thenar eminence)","Skeletal muscle. It flexes the thumb at the metacarpophalangeal joint.",[["Origin","Flexor retinaculum and trapezium"],["Insertion","Base of the proximal phalanx of the thumb"],["Action","Flexes the thumb at the metacarpophalangeal joint"],["Innervation","Median nerve (recurrent branch)"]]],["Masseter — superficial part","Head: muscles of mastication","Superficial portion, the bulkiest, of the masseter, one of the most powerful muscles of the body relative to its size.",[["Origin","Inferior border of the anterior two thirds of the zygomatic arch"],["Insertion","Angle and lateral surface of the ramus of the mandible"],["Action","Elevates the mandible (closing the mouth) and helps in protrusion"],["Innervation","Mandibular nerve (V3), branch of the trigeminal, masseteric nerve"]]],["Superior colliculus","Brain: brainstem and cerebellum","Eminence of the roof of the midbrain that coordinates eye and head movements toward visual stimuli (visual reflexes).",[["Pathway","Visual"]]],["Superior frontal gyrus","Brain: cerebral cortex","Gyrus of the cerebral cortex (grey matter). It contains the supplementary motor area and takes part in executive functions, self-awareness and working memory.",[["Lobe","Frontal"]]],["Superior mesenteric artery","Major arteries (abdominal)","It arises from the aorta at L1 and supplies the small intestine (from the second part of the duodenum), the caecum, the ascending colon and 2/3 of the transverse colon.",[]],["Superior mesenteric vein","Major veins (portal system)","It drains the small intestine, the caecum and the ascending and transverse colon. With the splenic vein it forms the portal vein, which carries absorbed nutrients to the liver.",[]],["Longus colli — superior oblique part","Neck (prevertebral)","Skeletal muscle. It flexes the neck.",[["Origin","Anterior tubercles of the transverse processes of C3–C5"],["Insertion","Anterior tubercle of the atlas"],["Action","Flexes the neck"],["Innervation","Anterior rami of C2–C6"]]],["Superior parietal lobule and precuneus","Brain: cerebral cortex","Gyrus of the cerebral cortex (grey matter). It integrates visual and somatosensory information to orient the body in space and guide movements. The precuneus, on the medial surface, takes part in episodic memory and self-awareness.",[["Lobe","Parietal"]]],["Superior vena cava","Major veins","Formed by the union of the two brachiocephalic veins. It collects blood from the head, neck, upper limbs and thorax and drains into the right atrium.",[["Length","≈7 cm"]]],["Supinator","Upper limb: forearm (posterior)","Skeletal muscle. It supinates the forearm.",[["Origin","Lateral epicondyle, radial collateral and annular ligaments and supinator crest of the ulna"],["Insertion","Proximal third of the radius (lateral, posterior and anterior surfaces)"],["Action","Supinates the forearm"],["Innervation","Radial nerve (deep branch)"]]],["Supramarginal gyrus","Brain: cerebral cortex","Gyrus of the cerebral cortex (grey matter). It surrounds the end of the lateral sulcus. It takes part in spatial perception, praxis and, in the dominant hemisphere, in the phonological processing of language.",[["Lobe","Parietal (inferior)"],["Area","Brodmann 40"]]],["Supraspinatus","Upper limb: shoulder (rotator cuff)","Part of the rotator cuff; its tendon is the one most frequently injured in the shoulder.",[["Origin","Supraspinous fossa of the scapula"],["Insertion","Superior facet of the greater tubercle of the humerus"],["Action","Initiates abduction of the arm and stabilises the humeral head"],["Innervation","Suprascapular nerve (C5–C6)"]]],["Talus (astragalus)","Foot: tarsus","Short bone of the tarsus. The seven tarsal bones form the posterior skeleton of the foot. It transmits the weight of the tibia to the rest of the foot; it has no muscle attachments and is largely covered by articular cartilage.",[]],["Temporal bone","Skull","Paired bone of the lateral wall and base of the skull. Its petrous part houses the middle and inner ear and it articulates with the mandible at the temporomandibular joint.",[["Parts","Squamous part, petrous part, tympanic part, styloid process and mastoid process"]]],["Temporalis","Head: muscles of mastication","Skeletal muscle. It elevates the mandible; its posterior fibres retract it.",[["Origin","Temporal fossa and temporal fascia"],["Insertion","Coronoid process and anterior border of the ramus of the mandible"],["Action","Elevates the mandible; its posterior fibres retract it"],["Innervation","Mandibular nerve (V3), branch of the trigeminal, deep temporal nerves"]]],["Temporoparietalis","Head: muscles of facial expression","Skeletal muscle. It tenses the scalp and elevates the auricle.",[["Origin","Temporal fascia above the auricle"],["Insertion","Lateral border of the epicranial aponeurosis"],["Action","Tenses the scalp and elevates the auricle"],["Innervation","Facial nerve (VII), temporal branches"]]],["Tendinous arch of the levator ani","Pelvis: pelvic floor","Thickening of the fascia of the obturator internus that extends from the pubis to the ischial spine and gives origin to part of the levator ani.",[]],["Tensor fasciae latae","Lower limb: hip and gluteal region","Skeletal muscle. It abducts, flexes and medially rotates the thigh; it stabilises the knee in extension.",[["Origin","Anterior superior iliac spine"],["Insertion","Iliotibial tract"],["Action","Abducts, flexes and medially rotates the thigh; stabilises the knee in extension"],["Innervation","Superior gluteal nerve (L4–S1)"]]],["Tenth rib","Thoracic cage","False rib (vertebrochondral): its cartilage joins that of the rib above, forming the costal arch.",[["No.","10th of 12 pairs"]]],["T10 vertebra","Vertebral column","Thoracic vertebra: it has costal facets on the body and on the transverse processes to articulate with the ribs, and a long spinous process pointing downward.",[]],["Teres major","Upper limb: shoulder","Skeletal muscle. It adducts, extends and medially rotates the arm.",[["Origin","Inferior angle of the scapula (posterior surface)"],["Insertion","Crest of the lesser tubercle of the humerus"],["Action","Adducts, extends and medially rotates the arm"],["Innervation","Lower subscapular nerve (C5–C6)"]]],["Teres minor","Upper limb: shoulder (rotator cuff)","Skeletal muscle. It laterally rotates the arm and stabilises the shoulder.",[["Origin","Lateral border of the scapula"],["Insertion","Inferior facet of the greater tubercle of the humerus"],["Action","Laterally rotates the arm and stabilises the shoulder"],["Innervation","Axillary nerve (C5–C6)"]]],["Testis","Male reproductive system","Male gonad, ovoid (≈4–5 cm), housed in the scrotum. Its seminiferous tubules produce sperm and the Leydig cells produce testosterone.",[["Size","≈4–5 × 2.5 cm"],["Hormone","Testosterone"]]],["Thalamus","Brain: deep nuclei","Ovoid mass of grey matter on each side of the third ventricle. It is the great relay station: almost all sensory information (except smell) passes through it before reaching the cortex. It also regulates wakefulness and attention.",[["Group","Diencephalon"]]],["C3 vertebra","Vertebral column","Typical cervical vertebra: small body, transverse foramina through which the vertebral artery ascends (C1–C6) and a short spinous process, bifid in C3–C6.",[]],["Third costal cartilage","Thoracic cage","Hyaline cartilage that joins the anterior end of the rib to the sternum. Its elasticity allows the thoracic cage to expand during breathing.",[]],["L3 vertebra","Vertebral column","Lumbar vertebra: the largest, with a kidney-shaped, robust body adapted to bear the weight of the trunk. Its spinous processes are short and horizontal.",[]],["Third lumbrical of the foot","Lower limb: foot (sole, 2nd layer)","Skeletal muscle. It flexes the metatarsophalangeal joint and extends the interphalangeal joints.",[["Origin","Tendons of the flexor digitorum longus"],["Insertion","Extensor expansion of the fourth toe"],["Action","Flexes the metatarsophalangeal joint and extends the interphalangeal joints"],["Innervation","Lateral plantar nerve (S2–S3)"]]],["Third metacarpal","Hand: metacarpus","Long bone of the palm of the hand. Its base articulates with the carpus and its head with the proximal phalanx (knuckle). Metacarpal of the middle finger; it has the styloid process at its base.",[]],["Third metatarsal","Foot: metatarsus","Long bone of the forefoot. Its base articulates with the tarsus and its head with the proximal phalanx; the metatarsal heads rest on the ground during walking.",[]],["Third plantar interosseous","Lower limb: foot (sole, 4th layer)","Skeletal muscle. It adducts the toe toward the axis of the second toe.",[["Origin","Medial surface of the fifth metatarsal"],["Insertion","Base of the proximal phalanx of the fifth toe (medial side)"],["Action","Adducts the toe toward the axis of the second toe"],["Innervation","Lateral plantar nerve (S2–S3)"]]],["Third rib","Thoracic cage","True rib (vertebrosternal): it joins the sternum directly through its own costal cartilage.",[["No.","3rd of 12 pairs"]]],["T3 vertebra","Vertebral column","Thoracic vertebra: it has costal facets on the body and on the transverse processes to articulate with the ribs, and a long spinous process pointing downward.",[]],["Third ventricle","Brain: ventricular system","Narrow, medial cavity between the two thalami, filled with cerebrospinal fluid. It communicates with the lateral ventricles and, through the aqueduct, with the fourth ventricle.",[]],["Thoracic rotator muscles","Back: deep muscles (erector spinae) (transversospinal)","Skeletal muscle. They stabilise and rotate the spine; proprioceptive function.",[["Origin","Transverse processes of the thoracic vertebrae"],["Insertion","Lamina or spinous process of the vertebra 1–2 levels above"],["Action","Stabilise and rotate the spine; proprioceptive function"],["Innervation","Posterior rami of the spinal nerves"]]],["Thyrohyoid","Neck (infrahyoid)","Skeletal muscle. It lowers the hyoid or elevates the larynx if the hyoid is fixed.",[["Origin","Oblique line of the thyroid cartilage"],["Insertion","Body and greater horn of the hyoid"],["Action","Lowers the hyoid or elevates the larynx if the hyoid is fixed"],["Innervation","C1 via the hypoglossal nerve (XII)"]]],["Thyroid cartilage","Airways","The largest cartilage of the larynx. Its two laminae join at the front forming the laryngeal prominence (\"Adam's apple\"), more marked in males. It protects the vocal cords, which attach to its inner surface.",[["Tissue","Hyaline cartilage"],["Level","C4–C5"]]],["Tibia","Lower limb","Medial and main bone of the leg, which bears body weight. Its anterior border is subcutaneous and its distal end forms the medial malleolus.",[["Type","Long bone"],["Joints","Knee, tibiofibular and ankle"]]],["Tibialis anterior","Lower limb: leg (anterior)","Its paralysis causes \"foot drop\". It dorsiflexes and inverts the foot.",[["Origin","Lateral condyle and upper half of the lateral surface of the tibia"],["Insertion","Medial cuneiform and base of the first metatarsal"],["Action","Dorsiflexion and inversion of the foot"],["Innervation","Deep fibular nerve (L4–L5)"]]],["Tibialis posterior","Lower limb: leg (posterior)","Skeletal muscle. Inversion and plantar flexion of the foot; it supports the medial longitudinal arch.",[["Origin","Interosseous membrane and posterior surfaces of the tibia and fibula"],["Insertion","Navicular tuberosity, cuneiforms, cuboid and bases of metatarsals 2–4"],["Action","Inversion and plantar flexion of the foot; supports the medial longitudinal arch"],["Innervation","Tibial nerve (S1–S2)"]]],["Trachea","Airways","Tube of ≈10–12 cm running from the larynx (C6) to the carina (T4–T5), where it divides into the two main bronchi. It is supported by 16–20 C-shaped rings of hyaline cartilage, open at the back.",[["Length","≈10–12 cm"],["Diameter","≈2 cm"]]],["Adductor hallucis — transverse head","Lower limb: foot (sole, 3rd layer)","Skeletal muscle. It adducts the big toe; it supports the transverse arch.",[["Origin","Plantar ligaments of the 3rd–5th metatarsophalangeal joints"],["Insertion","Base of the proximal phalanx of the big toe (lateral side)"],["Action","Adducts the big toe; supports the transverse arch"],["Innervation","Lateral plantar nerve (S2–S3)"]]],["Adductor pollicis — transverse head","Upper limb: hand","Skeletal muscle. It adducts the thumb (lateral pinch).",[["Origin","Palmar surface of the third metacarpal"],["Insertion","Base of the proximal phalanx of the thumb (ulnar side)"],["Action","Adducts the thumb (lateral pinch)"],["Innervation","Ulnar nerve (deep branch)"]]],["Trapezius — transverse part","Back: superficial muscles","Skeletal muscle. It retracts the scapula (brings it toward the spine).",[["Origin","Spinous processes of C7–T3"],["Insertion","Acromion and spine of the scapula"],["Action","Retracts the scapula (brings it toward the spine)"],["Innervation","Accessory nerve (XI)"]]],["Transversus abdominis","Abdomen","Skeletal muscle. It compresses the abdominal contents and stabilises the lumbar spine.",[["Origin","Costal cartilages 7–12, thoracolumbar fascia, iliac crest and inguinal ligament"],["Insertion","Linea alba, pubic crest and pectineal line"],["Action","Compresses the abdominal contents and stabilises the lumbar spine"],["Innervation","Thoracoabdominal, iliohypogastric and ilioinguinal nerves (T7–L1)"]]],["Transversus thoracis","Thorax","Skeletal muscle. It lowers the costal cartilages (expiration).",[["Origin","Posterior surface of the sternum and xiphoid process"],["Insertion","Inner surface of costal cartilages 2–6"],["Action","Lowers the costal cartilages (expiration)"],["Innervation","Intercostal nerves T2–T6"]]],["Trapezium","Hand: carpus","Short bone of the carpus. The eight carpal bones are arranged in two rows and form the skeleton of the wrist. Distal row; it articulates in a saddle joint with the first metacarpal, which allows opposition of the thumb.",[]],["Trapezoid","Hand: carpus","Short bone of the carpus. The eight carpal bones are arranged in two rows and form the skeleton of the wrist. Distal row; the smallest of the row, it articulates with the second metacarpal.",[]],["Tricuspid valve","Heart","Right atrioventricular valve, with three cusps. It prevents the backflow of blood from the right ventricle to the right atrium during systole.",[["Cusps","Anterior, posterior and septal"]]],["Triquetrum","Hand: carpus","Short bone of the carpus. The eight carpal bones are arranged in two rows and form the skeleton of the wrist. Proximal row; it articulates with the pisiform on its palmar surface.",[]],["Tuber cinereum","Brain: deep nuclei","Eminence of grey matter at the base of the hypothalamus, between the optic chiasm and the mammillary bodies; the pituitary stalk arises from it.",[["Group","Diencephalon"]]],["Twelfth rib","Thoracic cage","Floating rib: its anterior end ends free in the muscles of the abdominal wall.",[["No.","12th of 12 pairs"]]],["T12 vertebra","Vertebral column","Thoracic vertebra: it has costal facets on the body and on the transverse processes to articulate with the ribs, and a long spinous process pointing downward. Its costal facets are complete and single; it no longer articulates with the transverse processes.",[]],["Ulna","Upper limb","Medial bone of the forearm. Its olecranon forms the point of the elbow and its trochlear notch articulates with the humerus.",[["Type","Long bone"]]],["Extensor carpi ulnaris — ulnar head","Upper limb: forearm (posterior)","Skeletal muscle. It extends and adducts the wrist.",[["Origin","Posterior border of the ulna"],["Insertion","Base of the fifth metacarpal"],["Action","Extends and adducts the wrist"],["Innervation","Posterior interosseous nerve (of the radial)"]]],["Flexor carpi ulnaris — ulnar head","Upper limb: forearm (anterior)","Skeletal muscle. It flexes and adducts the wrist.",[["Origin","Olecranon and posterior border of the ulna"],["Insertion","Pisiform, hook of the hamate and fifth metacarpal"],["Action","Flexes and adducts the wrist"],["Innervation","Ulnar nerve (C7–T1)"]]],["Pronator teres — ulnar head","Upper limb: forearm (anterior)","Deep head of the pronator teres; the median nerve passes between the two heads.",[["Origin","Coronoid process of the ulna"],["Insertion","Lateral surface of the radius (middle third)"],["Action","Pronates the forearm"],["Innervation","Median nerve (C6–C8)"]]],["Upper central incisor","Mouth and teeth","Tooth with a shovel-shaped crown and a single root; it cuts food. Teeth are part of the digestive system (oral cavity). Adults have 32 permanent teeth; in this model the third molars (wisdom teeth) are missing. They are made of enamel, dentin, pulp and cementum.",[]],["Upper first molar","Mouth and teeth","Large molar with four cusps and three roots; it grinds food. It erupts at about 6 years of age. Teeth are part of the digestive system (oral cavity). Adults have 32 permanent teeth; in this model the third molars (wisdom teeth) are missing. They are made of enamel, dentin, pulp and cementum.",[]],["Upper first premolar","Mouth and teeth","Tooth with two cusps that crushes food; it usually has two roots. Teeth are part of the digestive system (oral cavity). Adults have 32 permanent teeth; in this model the third molars (wisdom teeth) are missing. They are made of enamel, dentin, pulp and cementum.",[]],["Lateral pterygoid — superior head","Head: muscles of mastication","Skeletal muscle. It stabilises the articular disc when the mouth closes.",[["Origin","Infratemporal surface of the greater wing of the sphenoid"],["Insertion","Capsule and disc of the temporomandibular joint"],["Action","Stabilises the articular disc when the mouth closes"],["Innervation","Mandibular nerve (V3), branch of the trigeminal"]]],["Upper lateral incisor","Mouth and teeth","Cutting tooth, smaller than the central incisor, with a single root. Teeth are part of the digestive system (oral cavity). Adults have 32 permanent teeth; in this model the third molars (wisdom teeth) are missing. They are made of enamel, dentin, pulp and cementum.",[]],["Upper second molar","Mouth and teeth","Molar with three or four cusps and three roots. It erupts at about 12 years of age. Teeth are part of the digestive system (oral cavity). Adults have 32 permanent teeth; in this model the third molars (wisdom teeth) are missing. They are made of enamel, dentin, pulp and cementum.",[]],["Upper second premolar","Mouth and teeth","Tooth with two cusps that crushes food; it usually has one root. Teeth are part of the digestive system (oral cavity). Adults have 32 permanent teeth; in this model the third molars (wisdom teeth) are missing. They are made of enamel, dentin, pulp and cementum.",[]],["Upper canine","Mouth and teeth","Tooth with a pointed cusp that tears food. It has the longest root of the dentition. Teeth are part of the digestive system (oral cavity). Adults have 32 permanent teeth; in this model the third molars (wisdom teeth) are missing. They are made of enamel, dentin, pulp and cementum.",[]],["Ureter","Urinary system","Muscular duct of ≈25 cm that carries urine from the renal pelvis to the bladder by peristalsis. It has three narrowings where stones can lodge.",[["Length","≈25–30 cm"]]],["Urethra","Urinary system","Duct that carries urine from the bladder to the outside. In males (≈20 cm) it is also the pathway of semen and has prostatic, membranous and spongy portions.",[["Length (male)","≈18–20 cm"]]],["Urinary bladder","Urinary system","Hollow muscular organ located in the pelvis, behind the pubic symphysis. It stores urine; its wall (detrusor muscle) contracts during urination.",[["Capacity","≈400–600 ml"]]],["Vastus intermedius","Lower limb: thigh (anterior) (quadriceps)","Skeletal muscle. It extends the knee.",[["Origin","Anterior and lateral surfaces of the femoral shaft"],["Insertion","Tibial tuberosity via the patellar tendon"],["Action","Extends the knee"],["Innervation","Femoral nerve (L2–L4)"]]],["Vastus lateralis","Lower limb: thigh (anterior) (quadriceps)","The bulkiest head of the quadriceps.",[["Origin","Greater trochanter and lateral lip of the linea aspera"],["Insertion","Tibial tuberosity via the patellar tendon"],["Action","Extends the knee"],["Innervation","Femoral nerve (L2–L4)"]]],["Vastus medialis","Lower limb: thigh (anterior) (quadriceps)","Skeletal muscle. It extends the knee; its oblique fibres stabilise the patella.",[["Origin","Intertrochanteric line and medial lip of the linea aspera"],["Insertion","Tibial tuberosity via the patellar tendon"],["Action","Extends the knee; its oblique fibres stabilise the patella"],["Innervation","Femoral nerve (L2–L4)"]]],["Longus colli — vertical part","Neck (prevertebral)","Skeletal muscle. It flexes the neck.",[["Origin","Vertebral bodies of C5–T3"],["Insertion","Vertebral bodies of C2–C4"],["Action","Flexes the neck"],["Innervation","Anterior rami of C2–C6"]]],["Vomer","Skull","Unpaired, flat bone that forms the posteroinferior part of the nasal septum.",[]],["Heart (wall)","Heart","Fist-sized hollow muscular organ located in the middle mediastinum. It has four chambers (two atria and two ventricles). Its wall consists of endocardium, myocardium and epicardium. It beats about 100,000 times a day.",[["Weight","≈300 g"],["Layers","Endocardium · myocardium · epicardium"],["Cardiac output","≈5 L/min at rest"]]],["White matter of the cerebral hemispheres","Brain: white matter","Mass of myelinated axons located under the cortex. It contains association fibres (joining areas of the same hemisphere), commissural fibres (joining both hemispheres) and projection fibres (joining the cortex with lower structures).",[]],["Xiphoid process","Thoracic cage","Small, lower end of the sternum. It is cartilaginous in young people and ossifies with age; the linea alba inserts on it.",[]],["Zygomatic bone","Skull","Paired bone that forms the cheekbone and part of the lateral wall of the orbit. With the zygomatic process of the temporal bone it forms the zygomatic arch.",[]],["Zygomaticus major","Head: muscles of facial expression","Skeletal muscle. It pulls the angle of the mouth up and back (smile).",[["Origin","Lateral surface of the zygomatic bone"],["Insertion","Angle of the mouth (modiolus)"],["Action","Pulls the angle of the mouth up and back (smile)"],["Innervation","Facial nerve (VII), zygomatic branches"]]],["Zygomaticus minor","Head: muscles of facial expression","Skeletal muscle. It elevates the upper lip.",[["Origin","Anterior surface of the zygomatic bone"],["Insertion","Upper lip"],["Action","Elevates the upper lip"],["Innervation","Facial nerve (VII), zygomatic branches"]]]]};
